
/* ===== SOURCE: upbonus.css ===== */
/* 001 — inline-style-1 */
:root{
    --brand-primary:#6b174e;
    --brand-primary-2:#8d3e78;
    --brand-accent:#8d62c4;
    --brand-soft:#f5eef8;
    --brand-bg:#f6f4f8;
    --brand-surface:#ffffff;
    --brand-text:#211722;
    --brand-muted:#766b77;
    --brand-border:#e4dbe8;
    --brand-success:#16805c;
    --brand-warning:#b56a00;
    --brand-danger:#bb304c;
    --brand-radius:16px;
    --brand-shadow:0 12px 34px rgba(56,26,53,.10);
    --sidebar-w:252px;
    --topbar-h:68px;
    --font:"Roboto",Arial,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  }
  *{box-sizing:border-box}
  html,body{margin:0;min-height:100%;font-family:var(--font);color:var(--brand-text);background:var(--brand-bg)}
  body{overflow-x:hidden}
  button,input,select,textarea{font:inherit}
  button{cursor:pointer}
  a{color:inherit}
  .hidden{display:none!important}
  .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
  .icon{width:20px;height:20px;display:inline-grid;place-items:center;flex:0 0 20px}
  .app{min-height:100dvh}
  .toast-wrap{position:fixed;top:18px;right:18px;z-index:5000;display:grid;gap:10px;max-width:min(380px,calc(100vw - 36px))}
  .toast{background:#fff;border:1px solid var(--brand-border);box-shadow:var(--brand-shadow);padding:12px 14px;border-radius:14px;display:flex;gap:10px;align-items:flex-start;animation:toastIn .2s ease}
  .toast strong{display:block;font-size:14px}.toast small{display:block;color:var(--brand-muted);margin-top:2px;line-height:1.35}
  @keyframes toastIn{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}

  /* LOGIN */
