  .form-grid{display:grid;gap:14px}.field label{display:block;font-size:12px;font-weight:800;margin-bottom:7px}.field input,.field select,.field textarea{width:100%;border:1px solid var(--brand-border);background:#fff;border-radius:12px;padding:13px 14px;outline:none;min-height:48px}.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--brand-primary);box-shadow:0 0 0 3px color-mix(in srgb,var(--brand-primary) 11%,transparent)}
