  .top-actions{margin-left:auto;display:flex;align-items:center;gap:8px}.icon-btn{width:42px;height:42px;border-radius:12px;border:1px solid var(--brand-border);background:#fff;display:grid;place-items:center;position:relative}.icon-btn:hover{background:var(--brand-soft)}.badge-dot{position:absolute;top:6px;right:6px;min-width:16px;height:16px;border-radius:8px;background:var(--brand-danger);color:#fff;font-size:10px;display:grid;place-items:center;padding:0 4px}
