  /* ROLE APP */
  .role-app{height:100dvh;min-height:0;display:grid;grid-template-columns:var(--sidebar-w) minmax(0,1fr);grid-template-rows:var(--topbar-h) minmax(0,1fr);overflow:hidden}
  .app:has(.role-app){height:100dvh;min-height:0;overflow:hidden}

