  .dashboard-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(310px,.5fr);gap:14px}.panel{background:#fff;border:1px solid var(--brand-border);border-radius:18px;min-width:0}.panel-head{padding:15px 16px;border-bottom:1px solid var(--brand-border);display:flex;align-items:center;justify-content:space-between;gap:12px}.panel-head h2,.panel-head h3{font-size:14px;margin:0}.panel-body{padding:16px}.quick-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.quick{border:1px solid var(--brand-border);background:#fff;border-radius:16px;padding:16px;text-align:left;min-height:152px;display:flex;flex-direction:column;justify-content:flex-start}.quick:hover{background:var(--brand-soft);border-color:var(--brand-accent)}.quick b{font-size:14px;display:block;margin-top:8px}.quick span{font-size:11px;color:var(--brand-muted);display:block;margin-top:6px;line-height:1.45}.list-clean{list-style:none;padding:0;margin:0}.list-item{display:flex;align-items:center;gap:10px;padding:11px 0;border-top:1px solid var(--brand-border)}.list-item:first-child{border-top:0}.list-item-main{min-width:0;flex:1}.list-item b{font-size:12px;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.list-item span{font-size:10px;color:var(--brand-muted);display:block;margin-top:3px}.status{display:inline-flex;align-items:center;border-radius:999px;padding:5px 8px;font-size:9px;font-weight:850;white-space:nowrap}.status.green{background:#e9f7f1;color:var(--brand-success)}.status.amber{background:#fff4dd;color:var(--brand-warning)}.status.red{background:#fff0f2;color:var(--brand-danger)}.status.gray{background:#f1eef2;color:#675e68}.status.purple{background:var(--brand-soft);color:var(--brand-primary)}

  /* TABLES / FILTERS */
  .toolbar{background:#fff;border:1px solid var(--brand-border);border-radius:16px;padding:12px;margin-bottom:12px;display:flex;align-items:center;gap:9px;flex-wrap:wrap}.toolbar .search{min-width:min(320px,100%);flex:1;position:relative}.toolbar input,.toolbar select{height:40px;border:1px solid var(--brand-border);border-radius:10px;padding:0 11px;background:#fff;outline:none}.toolbar .search input{width:100%;padding-left:36px}.toolbar .search span{position:absolute;left:12px;top:9px;color:var(--brand-muted)}.toolbar .spacer{flex:1}.compact-btn{min-height:38px;border:1px solid var(--brand-border);background:#fff;border-radius:10px;padding:8px 11px;font-size:11px;font-weight:800;display:inline-flex;align-items:center;gap:7px}.compact-btn:hover{background:var(--brand-soft)}.compact-btn.primary{background:var(--brand-primary);color:#fff;border-color:var(--brand-primary)}
