/* 007 — ub-safe-brand-fonts-v3 */
/* =========================================================
   UP BONUS — SAFE VISUAL OVERRIDE
   Tylko CSS. Bez zmian w JS, Supabase i procesach.
   Brand: #490F30 / #FF8500 / #FFFFFF / #000000
   ========================================================= */

:root{
  --brand-primary:#490F30 !important;
  --brand-primary-2:#490F30 !important;
  --brand-accent:#FF8500 !important;
  --brand-soft:rgba(73,15,48,.08) !important;
  --brand-bg:#FFFFFF !important;
  --brand-surface:#FFFFFF !important;
  --brand-text:#000000 !important;
  --brand-muted:#000000 !important;
  --brand-border:rgba(73,15,48,.20) !important;
}

/* ---------- Global readability ---------- */
html{font-size:16px}
body,
button,
input,
select,
textarea{
  color:#000000;
  font-size:15px;
  line-height:1.45;
}

/* ---------- Topbar ---------- */
.topbar-brand b{font-size:18px !important}
.topbar-brand small{font-size:13px !important;color:#000 !important}
.top-search input{font-size:15px !important}
.profile-btn b{font-size:14px !important}
.profile-btn span{font-size:12px !important}
.employee-balance-pill span{font-size:12px !important}
.employee-balance-pill b{font-size:16px !important}
.badge-dot{font-size:11px !important}

/* ---------- Sidebar ---------- */
.sidebar-context b{font-size:15px !important}
.sidebar-context span{font-size:12px !important;color:#000 !important}
.menu-group-label{font-size:11px !important;color:#000 !important}
.menu-btn{
  font-size:15px !important;
  min-height:46px !important;
  color:#000 !important;
}
.menu-btn.active{
  background:#490F30 !important;
  color:#fff !important;
  box-shadow:inset 4px 0 0 #FF8500 !important;
}
.menu-btn.active svg{color:#fff !important}
.menu-btn:hover{background:rgba(255,133,0,.12) !important}
.menu-btn .count{font-size:11px !important}

/* ---------- Page headings ---------- */
.page-head h1{font-size:31px !important}
.page-head p{font-size:15px !important;color:#000 !important;line-height:1.5}
.section-head h2{font-size:26px !important}
.section-head p{font-size:15px !important;color:#000 !important}
.panel-head h2,
.panel-head h3{font-size:17px !important}

/* ---------- Cards / dashboard ---------- */
.stat b{font-size:28px !important}
.stat span{font-size:13px !important;color:#000 !important}
.stat .trend{font-size:12px !important}
.quick b{font-size:16px !important}
.quick span{font-size:13px !important;color:#000 !important;line-height:1.5}
.role-card h3{font-size:18px !important}
.role-card p{font-size:14px !important;color:#000 !important}
.role-meta{font-size:13px !important;color:#000 !important}
.role-card .role-badge{font-size:11px !important}

/* ---------- Lists ---------- */
.list-item b{font-size:14px !important}
.list-item span{font-size:12px !important;color:#000 !important}
.status{
  font-size:11px !important;
  padding:6px 9px !important;
}

/* ---------- Tables ---------- */
table,
.data-table,
.v14-request-table,
.v111-cancel-table{
  font-size:14px !important;
}
table th,
.data-table th,
.v14-request-table th,
.v111-cancel-table th{
  font-size:13px !important;
  color:#000 !important;
}
table td,
.data-table td,
.v14-request-table td,
.v111-cancel-table td{
  font-size:14px !important;
  line-height:1.5 !important;
  color:#000 !important;
}

/* ---------- Forms / buttons ---------- */
.field label{font-size:14px !important}
.field input,
.field select,
.field textarea{
  font-size:15px !important;
}
.primary-btn,
.secondary-btn,
.ghost-btn,
.danger-btn,
.link-btn,
.compact-btn{
  font-size:14px !important;
}
.primary-btn{
  background:#490F30 !important;
  color:#fff !important;
}
.primary-btn:hover{filter:none !important;background:#5b173d !important}
.secondary-btn{
  background:#fff !important;
  color:#000 !important;
  border-color:#490F30 !important;
}
.link-btn{color:#490F30 !important}

/* ---------- Employee portal ---------- */
.employee-dashboard p{
  font-size:14px !important;
  line-height:1.55 !important;
}
.employee-section h2{font-size:22px !important}
.employee-section h3{font-size:17px !important}
.employee-section p{font-size:14px !important}
.employee-program .amount{font-size:24px !important}
.wallet-total b,
.v14-ewallet-main b{font-size:31px !important}
.wallet-mini span{font-size:13px !important}
.wallet-mini b{font-size:17px !important}

/* ---------- Account / role picker ---------- */
.hero-side p{font-size:15px !important;color:#000 !important}
.context-line b{font-size:14px !important}
.context-line span{font-size:13px !important;color:#000 !important}
.portal-option b{font-size:15px !important}
.portal-option span{font-size:13px !important;color:#000 !important}

/* ---------- Modal ---------- */
.modal p,
.modal span,
.modal small{font-size:13px}
.modal h3{font-size:20px}
.modal label{font-size:14px}

/* =========================================================
   Brand unification — remove stray purple tones
   ========================================================= */

/* Main dark brand surfaces */
.hero-main,
.employee-hero,
.employee-banner,
.login-brand,
.v14-ewallet-main,
.v20-hero,
.v103-hero,
.v107-hero{
  background:#490F30 !important;
  color:#fff !important;
}

/* v137: removed broad descendant-white rule.
   Dark text is now assigned only to actual dark headers/hero content,
   never to every nested child card. */

/* Orange accents */
.eyebrow,
.role-icon,
.stat-icon,
.wallet-dot,
.quick-symbol,
.voucher-logo,
.request-icon,
.transaction-icon{
  color:#FF8500 !important;
}

/* Selected / active chips and small brand pills */
.category-chip.active,
.portal-option.active,
.compact-btn.active{
  border-color:#490F30 !important;
  background:#490F30 !important;
  color:#fff !important;
}

/* Soft brand backgrounds use only opacity of approved colors */
.brand-soft,
.v14-scope-note,
.demo-note,
.employee-alert{
  background:rgba(73,15,48,.06) !important;
}

/* Keep normal content high-contrast */
.panel,
.employee-section,
.stat,
.quick,
.role-card,
.info-card,
.wallet-mini,
.employee-program,
.employee-order,
.request-card,
.wellbeing-card,
.modal{
  color:#000 !important;
}

/* ---------- Large desktop ---------- */
@media (min-width:1400px){
  .menu-btn{font-size:15px !important}
  table td,.data-table td{font-size:14px !important}
  table th,.data-table th{font-size:13px !important}
  .page-head p{font-size:15px !important}
}

/* ---------- Smaller screens ---------- */
@media (max-width:1100px){
  body,button,input,select,textarea{font-size:14px}
  .menu-btn{font-size:13px !important}
  table td,.data-table td{font-size:12px !important}
  table th,.data-table th{font-size:12px !important}
}

