  .v26-role-head{width:100%;border:0;background:#fff;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 14px;text-align:left;cursor:pointer}
  .v26-role-head b{display:block}
  .v26-role-head span{display:block;color:var(--brand-muted);font-size:10px;margin-top:3px}
  .v26-role-body{padding:0 14px 13px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
  .v26-permission{border:1px solid var(--brand-border);border-radius:12px;padding:10px;display:flex;align-items:center;justify-content:space-between;gap:8px}
  .v26-permission span{font-size:11px}
  .v26-empty{text-align:center;padding:32px;color:var(--brand-muted)}
  .v26-program-actions{display:flex;gap:7px;justify-content:flex-end}
  .v26-inline-checks{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:10px}
  .v26-inline-check{border:1px solid var(--brand-border);border-radius:12px;padding:10px;display:flex;gap:8px;align-items:center}
  .v26-inline-check input{width:17px;height:17px}
  @media(max-width:1050px){
    .v26-grid{grid-template-columns:1fr}
    .v26-media-grid{grid-template-columns:1fr 1fr}
    .v26-context{grid-template-columns:1fr 1fr}
    .v26-context>button{grid-column:1/-1}
    .v26-summary,.v26-steps{grid-template-columns:1fr 1fr}
  }
  @media(max-width:680px){
    .v26-media-grid,.v26-summary,.v26-steps,.v26-role-body,.v26-inline-checks{grid-template-columns:1fr}
    .v26-context{grid-template-columns:1fr}
  }

/* 020 — ub-v27-employee-ux-style */
/* Wyszukiwarka — tekst nie jest ucinany */
  .top-search{overflow:visible}
  .top-search input{
    height:46px!important;
    line-height:46px!important;
    padding:0 16px 0 46px!important;
    font-size:14px!important;
    overflow:visible!important;
  }
  .top-search span{top:50%!important;transform:translateY(-50%)}
  .toolbar .search input,.employee-catalog-head .search input,.v25-rewards-toolbar input{
    line-height:42px!important;
    padding-top:0!important;
    padding-bottom:0!important;
  }

  /* Zdjęcie użytkownika */
  .avatar.v27-avatar{
    overflow:hidden;
    position:relative;
    flex:0 0 auto;
    border-radius:12px;
  }
  .avatar.v27-avatar img{
    position:absolute;
    inset:0;
    width:100%;
    height:100%;
    object-fit:cover;
    transform-origin:center;
    display:block;
    user-select:none;
    pointer-events:none;
  }
  .v27-profile-grid{display:grid;grid-template-columns:280px minmax(0,1fr);gap:22px;align-items:start}
  .v27-crop-stage{
    width:260px;height:260px;border-radius:28px;overflow:hidden;position:relative;
    background:linear-gradient(145deg,#f4edf7,#e8ddeb);border:1px solid var(--brand-border);
    cursor:grab;touch-action:none;display:grid;place-items:center;
  }
  .v27-crop-stage.dragging{cursor:grabbing}
  .v27-crop-stage img{
    position:absolute;inset:0;width:100%;height:100%;object-fit:cover;
    transform-origin:center;user-select:none;pointer-events:none;
  }
  .v27-crop-stage .v27-initials{
    width:100%;height:100%;display:grid;place-items:center;font-size:72px;font-weight:900;
    color:#fff;background:linear-gradient(135deg,var(--brand-primary),var(--brand-accent));
  }
  .v27-crop-hint{
    position:absolute;left:12px;right:12px;bottom:12px;background:rgba(24,13,23,.72);
    color:#fff;border-radius:12px;padding:8px 10px;text-align:center;font-size:10px;
    backdrop-filter:blur(8px);
  }
  .v27-profile-actions{display:grid;gap:12px}
  .v27-zoom-row{display:grid;grid-template-columns:100px 1fr 48px;gap:10px;align-items:center}
  .v27-zoom-row input{width:100%}
  .v27-profile-card{border:1px solid var(--brand-border);border-radius:16px;padding:14px;background:#fff}
  .v27-profile-card b{display:block;margin-bottom:4px}
  .v27-profile-card span{font-size:11px;color:var(--brand-muted)}

  /* Powiadomienia pojedyncze */
  .v27-notification-list{display:grid;gap:10px}
  .v27-notification{
    border:1px solid var(--brand-border);border-radius:15px;padding:13px;
    display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:11px;align-items:start;background:#fff;
  }
  .v27-notification.unread{border-color:#d5a4bd;background:#fffafd}
  .v27-notification-icon{width:38px;height:38px;border-radius:12px;background:var(--brand-soft);display:grid;place-items:center;font-size:18px}
  .v27-notification b{display:block;font-size:12px;margin-bottom:4px}
  .v27-notification p{font-size:10px;color:var(--brand-muted);line-height:1.45;margin:0}
  .v27-notification time{display:block;font-size:9px;color:var(--brand-muted);margin-top:6px}
  .v27-notification-actions{display:flex;gap:5px;align-items:center}
  .v27-notification-actions button{min-height:32px;border:1px solid var(--brand-border);background:#fff;border-radius:9px;padding:6px 9px;font-weight:800;font-size:10px}
  .v27-notification-actions .delete{width:32px;padding:0;color:#9b285f}

  /* UpBonek */
  .v27-upbonek-face{
    width:38px;height:38px;border-radius:14px;display:grid;place-items:center;
    background:linear-gradient(145deg,#ff8a00,#7b1754);box-shadow:0 8px 20px rgba(123,23,84,.22);
    color:#fff;font-size:21px;position:relative;
  }
  .v27-upbonek-face:after{
    content:"";position:absolute;width:8px;height:8px;border-radius:50%;background:#52d493;
    right:-2px;bottom:-2px;border:2px solid #fff;
  }
  .ub-ai-panel{width:min(390px,calc(100vw - 28px));max-height:min(690px,calc(100vh - 90px))}
  .ub-ai-body{overflow:auto}
  .v27-ai-action{
    display:inline-flex;align-items:center;gap:5px;border:1px solid #ddb6ca;background:#fff;
    color:var(--brand-primary);border-radius:10px;padding:7px 9px;margin-top:8px;font-weight:800;font-size:10px;
  }
  .v27-ai-context{
    margin:8px 0 2px;padding:9px;border:1px solid var(--brand-border);border-radius:12px;
    background:#fff;font-size:10px;color:var(--brand-muted);line-height:1.45;
  }

  /* Operacje portfela */
  .v27-operation-list{display:grid;gap:9px}
  .v27-operation{border:1px solid var(--brand-border);border-radius:15px;background:#fff;overflow:hidden}
  .v27-operation-head{
    width:100%;border:0;background:#fff;display:grid;
    grid-template-columns:42px minmax(0,1fr) auto auto;gap:11px;align-items:center;
    padding:13px;text-align:left;cursor:pointer;
  }
  .v27-operation-head:hover{background:#fffafd}
  .v27-operation-icon{width:38px;height:38px;border-radius:12px;background:var(--brand-soft);display:grid;place-items:center}
  .v27-operation-main b{display:block;font-size:12px}
  .v27-operation-main span{display:block;font-size:10px;color:var(--brand-muted);margin-top:3px}
  .v27-operation-amount{font-size:13px;font-weight:900;white-space:nowrap}
  .v27-operation-amount.plus{color:#087f5b}.v27-operation-amount.minus{color:#a31d55}
  .v27-operation-body{
    display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;
    border-top:1px solid var(--brand-border);padding:12px;background:#fcfafc;
  }
  .v27-operation-body div{border:1px solid var(--brand-border);border-radius:11px;padding:9px;background:#fff}
  .v27-operation-body span{display:block;font-size:9px;text-transform:uppercase;color:var(--brand-muted);letter-spacing:.05em}
  .v27-operation-body b{display:block;font-size:11px;margin-top:4px}

  /* Total Rewards miesięcznie */
  .v27-month-grid{
    display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px;margin-bottom:14px;
  }
  .v27-month-card{
    border:1px solid var(--brand-border);background:#fff;border-radius:13px;padding:11px;text-align:left;cursor:pointer;
  }
  .v27-month-card.active{border-color:var(--brand-primary);box-shadow:0 0 0 2px rgba(123,23,84,.1)}
  .v27-month-card span{display:block;font-size:9px;color:var(--brand-muted)}
  .v27-month-card b{display:block;font-size:16px;margin-top:4px}
  .v27-month-card em{display:block;font-size:9px;color:#087f5b;font-style:normal;margin-top:3px}
  .v27-month-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:14px}
  .v27-month-summary article{border:1px solid var(--brand-border);border-radius:15px;padding:14px;background:#fff}
  .v27-month-summary span{display:block;font-size:10px;color:var(--brand-muted)}
  .v27-month-summary b{display:block;font-size:23px;margin-top:5px}

  @media(max-width:900px){
    .v27-profile-grid{grid-template-columns:1fr}
    .v27-crop-stage{margin:auto}
    .v27-operation-body{grid-template-columns:1fr 1fr}
    .v27-month-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
    .v27-month-summary{grid-template-columns:1fr 1fr}
  }
  @media(max-width:560px){
    .v27-operation-head{grid-template-columns:38px minmax(0,1fr) auto}
    .v27-operation-head .v27-chevron{display:none}
    .v27-operation-body,.v27-month-grid,.v27-month-summary{grid-template-columns:1fr}
    .v27-notification{grid-template-columns:auto minmax(0,1fr)}
    .v27-notification-actions{grid-column:2}
  }

/* 021 — ub-v28-i18n-avatar-ui-style */
/* Pole wyszukiwania — pełna wysokość liter i poprawne odstępy */
  .top-search,
  .employee-catalog-head .search,
  .toolbar .search{
    overflow:visible!important;
    min-height:46px!important;
  }
  .top-search input,
  .employee-catalog-head .search input,
  .toolbar .search input{
    box-sizing:border-box!important;
    height:46px!important;
    min-height:46px!important;
    line-height:normal!important;
    padding:0 16px 0 46px!important;
    font-size:14px!important;
    font-family:inherit!important;
    overflow:visible!important;
    vertical-align:middle!important;
  }
  .top-search span,
  .employee-catalog-head .search>span,
  .toolbar .search>span{
    top:50%!important;
    transform:translateY(-50%)!important;
    line-height:1!important;
  }

  /* Przełącznik języka */
  .v28-language-select{
    height:40px;
    min-width:66px;
    padding:0 30px 0 12px;
    border:1px solid var(--brand-border);
    border-radius:12px;
    background:#fff;
    color:var(--brand-ink);
    font-weight:800;
    cursor:pointer;
  }

  /* Alerty pracownika — kompaktowe, dwukolumnowe i w rytmie pozostałych sekcji */
  .employee-alerts{
    display:grid!important;
    grid-template-columns:repeat(2,minmax(0,1fr))!important;
    gap:10px!important;
    width:100%!important;
    margin:0 0 14px!important;
  }
  .employee-alert{
    min-height:58px!important;
    padding:8px 11px!important;
    gap:9px!important;
    border-radius:15px!important;
    grid-template-columns:30px minmax(0,1fr) auto!important;
  }
  .employee-alert .alert-icon{
    width:30px!important;
    height:30px!important;
    border-radius:10px!important;
    font-size:15px!important;
  }
  .employee-alert b{
    font-size:11px!important;
    line-height:1.25!important;
  }
  .employee-alert span{
    font-size:9px!important;
    line-height:1.35!important;
    margin-top:2px!important;
  }
  .employee-alert button{
    font-size:10px!important;
    padding:5px 4px!important;
  }

  /* Zapisane zdjęcie również na pulpicie */
  .employee-hero.v28-has-avatar{
    padding-right:clamp(190px,22vw,285px)!important;
  }
  .employee-hero.v28-has-avatar:after{
    display:none!important;
  }
  .v28-dashboard-avatar{
    position:absolute;
    right:clamp(28px,5vw,72px);
    top:50%;
    width:clamp(120px,12vw,170px);
    height:clamp(120px,12vw,170px);
    transform:translateY(-50%);
    border-radius:38px;
    overflow:hidden;
    border:5px solid rgba(255,255,255,.55);
    box-shadow:0 18px 40px rgba(0,0,0,.25);
    background:rgba(255,255,255,.13);
  }
  .v28-dashboard-avatar img{
    width:100%;
    height:100%;
    object-fit:cover;
    display:block;
  }

  /* Zabawny avatar UpBonka — postać, nie znak firmowy */
  .v28-bonek-avatar{
    width:42px;
    height:42px;
    border-radius:16px 16px 18px 18px;
    display:grid;
    place-items:center;
    position:relative;
    background:linear-gradient(145deg,#ff9a18 0%,#ff6c34 52%,#7b1754 100%);
    box-shadow:0 9px 22px rgba(123,23,84,.28);
    color:#fff;
    font-weight:900;
    font-size:14px;
    letter-spacing:-2px;
    border:2px solid rgba(255,255,255,.8);
  }
  .v28-bonek-avatar:before{
    content:"";
    position:absolute;
    width:3px;
    height:9px;
    background:#7b1754;
    top:-9px;
    left:50%;
    transform:translateX(-50%);
    border-radius:3px;
  }
  .v28-bonek-avatar:after{
    content:"";
    position:absolute;
    width:8px;
    height:8px;
    border-radius:50%;
    background:#ffb826;
    top:-14px;
    left:50%;
    transform:translateX(-50%);
    border:2px solid #fff;
  }
  .v28-bonek-face{
    display:block;
    transform:translateY(1px);
    letter-spacing:-1px;
    text-shadow:0 1px 0 rgba(0,0,0,.15);
  }
  .v28-bonek-face small{
    display:block;
    height:4px;
    font-size:9px;
    line-height:4px;
    letter-spacing:0;
    margin-top:2px;
  }
  .ub-ai-human .v28-bonek-avatar{
    width:48px;
    height:48px;
    border-radius:18px;
  }

  @media(max-width:900px){
    .employee-alerts{grid-template-columns:1fr!important}
    .employee-hero.v28-has-avatar{padding-right:28px!important;padding-bottom:155px!important}
    .v28-dashboard-avatar{
      width:105px;height:105px;right:24px;top:auto;bottom:22px;transform:none;border-radius:28px;
    }
  }
  @media(max-width:600px){
    .employee-alert{grid-template-columns:28px minmax(0,1fr)!important}
    .employee-alert button{grid-column:2;justify-self:start;padding:0!important}
  }

/* 022 — ub-v29-hr-workflows-responsive-style */
/* Zdjęcie pracownika wyłącznie w prawym górnym profilu */
  .v28-dashboard-avatar{display:none!important}
  .employee-hero.v28-has-avatar{
    padding-right:clamp(25px,4vw,46px)!important;
    padding-bottom:clamp(25px,4vw,46px)!important;
  }
  .profile-btn .avatar.v27-avatar{
    width:44px!important;height:44px!important;border-radius:13px!important;
  }
  .profile-btn .avatar.v27-avatar img{width:100%!important;height:100%!important}

  /* Wyrównanie sekcji i kart */
  .employee-welcome{align-items:stretch}
  .employee-hero,.funds-card{height:100%}
  .employee-quick-grid,.employee-program-grid,.mini-product-row,.occasion-grid{align-items:stretch}
  .employee-quick,.employee-program,.mini-product,.occasion-card{height:100%}
  .employee-program{display:flex;flex-direction:column}
  .employee-program-footer{margin-top:auto!important}
  .employee-section{width:100%;box-sizing:border-box}
  .employee-section-head{align-items:flex-start}
  .employee-section-head>div{min-width:0}

  /* Ogólny rozmiar i responsywność przy 100% zoom */
  :root{--topbar-h:76px}
  .view-container{width:min(1540px,100%);margin:0 auto}
  .main-content{padding:18px clamp(14px,1.5vw,24px) 40px}
  .data-table th,.data-table td{padding:10px 11px}
  .page-head h1{font-size:clamp(24px,2vw,31px)}
  .page-head p{max-width:900px}
  .topbar{gap:12px;padding:0 16px}
  .topbar-brand{min-width:190px}
  .top-search{min-width:180px}
  .profile-btn{max-width:290px}
  .profile-btn>span:last-child{min-width:0}
  .profile-btn b,.profile-btn span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

  /* Techniczne białe napisy i tagi niewidoczne w MVP */
  .v11-tag-row{display:none!important}
  .v11-module-card.accent>p{display:none!important}
  .v11-module-card.accent{min-height:145px!important;justify-content:center!important}
  .v11-module-card.accent h2{margin-bottom:0!important}

  /* HR — wspólne komponenty */
  .v29-card{background:#fff;border:1px solid var(--brand-border);border-radius:18px;padding:16px;min-width:0}
  .v29-card h2,.v29-card h3{margin:0 0 5px}
  .v29-card>p{margin:0 0 13px;color:var(--brand-muted);font-size:11px;line-height:1.5}
  .v29-toolbar{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-bottom:11px}
  .v29-toolbar .search{min-width:260px;flex:1}
  .v29-toolbar select{min-height:42px}
  .v29-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:12px}
  .v29-summary article{background:#fff;border:1px solid var(--brand-border);border-radius:15px;padding:13px}
  .v29-summary span{display:block;color:var(--brand-muted);font-size:9px;text-transform:uppercase;letter-spacing:.06em}
  .v29-summary b{display:block;font-size:22px;margin-top:4px}
  .v29-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr);gap:14px}
  .v29-stack{display:grid;gap:14px}
  .v29-excel{border:1px solid var(--brand-border);border-radius:15px;overflow:auto;background:#fff}
  .v29-excel table{width:100%;border-collapse:collapse;min-width:930px}
  .v29-excel th,.v29-excel td{padding:10px 11px;border-bottom:1px solid var(--brand-border);border-right:1px solid var(--brand-border);text-align:left;vertical-align:middle}
  .v29-excel th:last-child,.v29-excel td:last-child{border-right:0}
  .v29-excel th{background:#faf7fb;font-size:9px;text-transform:uppercase;letter-spacing:.06em;white-space:nowrap}
  .v29-excel td{font-size:11px}
  .v29-excel td b{display:block}
  .v29-excel td small{display:block;color:var(--brand-muted);margin-top:3px}
  .v29-excel input,.v29-excel select{width:100%;min-height:36px;padding:7px 8px;border:1px solid var(--brand-border);border-radius:9px;background:#fff;font-size:11px}
  .v29-actions{display:flex;gap:5px;white-space:nowrap;flex-wrap:wrap}
  .v29-actions button{border:0;background:transparent;color:var(--brand-primary);font-weight:800;font-size:10px;cursor:pointer;padding:4px}
  .v29-import-actions{display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap;margin-top:12px}
  .v29-note{border:1px solid #f0d28e;background:#fff9e8;border-radius:13px;padding:11px;font-size:10px;line-height:1.45}
  .v29-success{border:1px solid #a9ddcb;background:#effaf6;border-radius:13px;padding:11px;font-size:10px;line-height:1.45}
  .v29-status-row{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}
  .v29-status-row span{background:var(--brand-soft);border-radius:999px;padding:5px 9px;font-size:9px;font-weight:800}
  .v29-detail-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
  .v29-detail-item{border:1px solid var(--brand-border);border-radius:12px;padding:10px}
  .v29-detail-item span{display:block;color:var(--brand-muted);font-size:9px;text-transform:uppercase}
  .v29-detail-item b{display:block;margin-top:4px;font-size:12px}
  .v29-reminder-box{display:flex;align-items:center;gap:9px;flex-wrap:wrap;border:1px solid var(--brand-border);border-radius:14px;padding:11px;background:#fff}
  .v29-reminder-box input[type="number"]{width:70px}
  .v29-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin-bottom:12px}
  .v29-step{border:1px solid var(--brand-border);border-radius:14px;padding:11px;background:#fff;display:flex;gap:8px}
  .v29-step i{font-style:normal;width:26px;height:26px;border-radius:8px;display:grid;place-items:center;background:var(--brand-soft);color:var(--brand-primary);font-weight:900}
  .v29-step b{display:block;font-size:11px}
  .v29-step span{display:block;font-size:9px;color:var(--brand-muted);line-height:1.4;margin-top:3px}
  .v29-message-preview{border:1px solid var(--brand-border);border-radius:15px;padding:14px;background:linear-gradient(145deg,#fff,#fbf7fb)}
  .v29-message-preview b{display:block;font-size:14px;margin-bottom:7px}
  .v29-message-preview p{margin:0;color:var(--brand-muted);font-size:11px;line-height:1.55}
  .v29-budget-flow{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px;margin:12px 0}
  .v29-budget-flow article{border:1px solid var(--brand-border);border-radius:12px;padding:10px;background:#fff;text-align:center}
  .v29-budget-flow b{display:block;font-size:10px}
  .v29-budget-flow span{display:block;color:var(--brand-muted);font-size:8px;margin-top:3px}
  .v29-inline{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
  .v29-inline .field{flex:1;min-width:180px}
