/* 023 — ub-v30-partner-catalog-card-graphics-style */
/* Karty benefitowe: serce i etykieta nie nachodzą na siebie */
  .benefit-card{position:relative}
  .benefit-cover{
    position:relative;
    overflow:hidden;
    height:138px!important;
    padding:0!important;
    background:#f7f2f8!important;
  }
  .benefit-card .favorite-heart{
    position:absolute!important;
    top:10px!important;
    right:10px!important;
    z-index:8!important;
    width:34px!important;
    height:34px!important;
    border-radius:11px!important;
    background:rgba(255,255,255,.96)!important;
    box-shadow:0 6px 16px rgba(35,17,32,.15)!important;
  }
  .benefit-cover .discount{
    top:auto!important;
    right:auto!important;
    left:10px!important;
    bottom:10px!important;
    z-index:5!important;
    max-width:calc(100% - 62px);
    overflow:hidden;
    text-overflow:ellipsis;
    white-space:nowrap;
  }
  .v30-product-art{
    width:100%;
    height:100%;
    display:block;
  }
  .v30-product-art svg{
    display:block;
    width:100%;
    height:100%;
  }
  .mini-product .mini-logo{
    overflow:hidden;
    padding:0!important;
    height:70px!important;
  }
  .mini-product .mini-logo .v30-product-art{height:70px}
  .mini-product .favorite-heart{
    z-index:7!important;
    box-shadow:0 5px 14px rgba(35,17,32,.13)!important;
  }

  /* Panel klienta / partnera */
  .v30-partner-note{
    display:flex;
    gap:11px;
    align-items:flex-start;
    border:1px solid #d9c7e1;
    background:#fbf8fd;
    border-radius:15px;
    padding:12px 14px;
    margin-bottom:13px;
    font-size:11px;
    line-height:1.5;
  }
  .v30-partner-note i{
    width:34px;height:34px;flex:0 0 34px;border-radius:11px;
    display:grid;place-items:center;background:var(--brand-soft);font-style:normal;
  }
  .v30-partner-note b{display:block;margin-bottom:3px}
  .v30-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:13px}
  .v30-kpis article{background:#fff;border:1px solid var(--brand-border);border-radius:15px;padding:14px}
  .v30-kpis span{display:block;color:var(--brand-muted);font-size:9px;text-transform:uppercase;letter-spacing:.06em}
  .v30-kpis b{display:block;font-size:23px;margin-top:5px}
  .v30-toolbar{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-bottom:11px}
  .v30-toolbar .search{flex:1;min-width:270px}
  .v30-toolbar select{min-height:42px}
  .v30-table{border:1px solid var(--brand-border);border-radius:16px;overflow:auto;background:#fff}
  .v30-table table{width:100%;min-width:1120px;border-collapse:collapse}
  .v30-table th,.v30-table td{
    padding:10px 11px;border-right:1px solid var(--brand-border);
    border-bottom:1px solid var(--brand-border);text-align:left;vertical-align:middle;
  }
  .v30-table th:last-child,.v30-table td:last-child{border-right:0}
  .v30-table th{background:#faf7fb;font-size:9px;text-transform:uppercase;letter-spacing:.055em;white-space:nowrap}
  .v30-table td{font-size:11px}
  .v30-product-cell{display:flex;align-items:center;gap:10px;min-width:210px}
  .v30-thumb{width:72px;height:46px;border-radius:10px;overflow:hidden;flex:0 0 72px;border:1px solid var(--brand-border)}
  .v30-thumb .v30-product-art{height:46px}
  .v30-product-cell b{display:block}
  .v30-product-cell small{display:block;color:var(--brand-muted);margin-top:2px}
  .v30-chip-row{display:flex;gap:5px;flex-wrap:wrap}
  .v30-chip{display:inline-flex;align-items:center;border-radius:999px;padding:4px 7px;background:var(--brand-soft);font-size:9px;font-weight:800}
  .v30-chip.ok{background:#eaf8f2;color:#087f5b}
  .v30-chip.warn{background:#fff5dc;color:#9a6200}
  .v30-chip.no{background:#f5f2f5;color:#746974}
  .v30-actions{display:flex;gap:6px;flex-wrap:wrap;white-space:nowrap}
  .v30-actions button{border:0;background:transparent;color:var(--brand-primary);font-weight:850;font-size:10px;cursor:pointer;padding:4px}
  .v30-switch-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:9px}
  .v30-check{
    display:flex;align-items:flex-start;gap:9px;border:1px solid var(--brand-border);
    border-radius:12px;padding:10px;background:#fff;
  }
  .v30-check input{width:17px;height:17px;margin-top:1px}
  .v30-check b{display:block;font-size:11px}
  .v30-check small{display:block;color:var(--brand-muted);font-size:9px;line-height:1.4;margin-top:3px}
  .v30-program-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  .v30-dashboard-grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(290px,.7fr);gap:13px}
  .v30-panel{background:#fff;border:1px solid var(--brand-border);border-radius:17px;padding:15px}
  .v30-panel h2{margin:0 0 5px}
  .v30-panel>p{margin:0 0 12px;color:var(--brand-muted);font-size:11px}
  .v30-activity{display:grid;gap:8px}
  .v30-activity article{display:flex;gap:10px;align-items:center;border:1px solid var(--brand-border);border-radius:13px;padding:10px}
  .v30-activity i{width:34px;height:34px;display:grid;place-items:center;border-radius:10px;background:var(--brand-soft);font-style:normal}
  .v30-activity b{display:block;font-size:11px}
  .v30-activity span{display:block;color:var(--brand-muted);font-size:9px;margin-top:2px}
  @media(max-width:1100px){
    .v30-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}
    .v30-dashboard-grid{grid-template-columns:1fr}
  }
  @media(max-width:680px){
    .v30-kpis,.v30-switch-grid,.v30-program-grid{grid-template-columns:1fr}
    .v30-toolbar>*{width:100%}
    .v30-toolbar .search{min-width:0}
  }

/* 024 — ub-v31-catalog-menu-stability-style */
/* =========================================================
     KATALOG — wyszukiwarka, filtry i kategorie bez przycinania
     ========================================================= */
  .employee-catalog-controls{
    display:grid!important;
    grid-template-columns:minmax(320px,1fr) minmax(175px,220px) minmax(175px,205px) minmax(150px,180px) auto!important;
    gap:10px!important;
    align-items:stretch!important;
    margin-bottom:14px!important;
  }
  .employee-catalog-controls .search{
    position:relative!important;
    display:block!important;
    width:100%!important;
    min-width:0!important;
    height:46px!important;
    overflow:visible!important;
  }
  .employee-catalog-controls .search > span{
    position:absolute!important;
    left:14px!important;
    top:50%!important;
    transform:translateY(-50%)!important;
    z-index:2!important;
    line-height:1!important;
    pointer-events:none!important;
    color:var(--brand-muted)!important;
  }
  .employee-catalog-controls .search input{
    display:block!important;
    box-sizing:border-box!important;
    width:100%!important;
    max-width:none!important;
    min-width:0!important;
    height:46px!important;
    min-height:46px!important;
    line-height:1.35!important;
    margin:0!important;
    padding:0 15px 0 45px!important;
    border:1px solid var(--brand-border)!important;
    border-radius:13px!important;
    background:#fff!important;
    color:var(--brand-ink)!important;
    font:inherit!important;
    font-size:13px!important;
    outline:none!important;
    overflow:visible!important;
    text-overflow:ellipsis!important;
  }
  .employee-catalog-controls .search input:focus{
    border-color:var(--brand-primary)!important;
    box-shadow:0 0 0 3px rgba(123,23,84,.09)!important;
  }
  .employee-catalog-controls select,
  .employee-catalog-controls .filter-favorite,
  .employee-catalog-controls .secondary-btn,
  .employee-catalog-controls .v19-wallet-filter{
    box-sizing:border-box!important;
    width:100%!important;
    min-width:0!important;
    min-height:46px!important;
    height:46px!important;
    margin:0!important;
  }
  .employee-catalog-controls .v19-wallet-filter{
    display:flex!important;
    align-items:center!important;
    justify-content:flex-start!important;
    padding:7px 11px!important;
    overflow:hidden!important;
  }
  .employee-catalog-controls .v19-wallet-filter > span{
    min-width:0!important;
    overflow:hidden!important;
  }
  .employee-catalog-controls .v19-wallet-filter > span,
  .employee-catalog-controls .v19-filter-help{
    line-height:1.15!important;
  }
  .employee-catalog-controls .secondary-btn{
    padding-inline:14px!important;
    white-space:nowrap!important;
  }

  /* Kategorie zawijają się do kolejnych wierszy — nic nie znika za krawędzią */
  .v15-category-wrap,
  .category-scroll{
    display:flex!important;
    flex-wrap:wrap!important;
    align-items:center!important;
    gap:8px!important;
    width:100%!important;
    overflow:visible!important;
    max-width:100%!important;
    padding:2px 0 12px!important;
    scrollbar-width:none!important;
  }
  .v15-category-chip,
  .category-chip{
    flex:0 0 auto!important;
    max-width:100%!important;
    min-height:38px!important;
    padding:8px 13px!important;
    line-height:1.2!important;
    white-space:normal!important;
    text-align:center!important;
  }

  /* Teksty kart i sekcji nie są obcinane */
  .employee-section,
  .employee-dashboard,
  .benefit-card,
  .benefit-body,
  .benefit-body h3,
  .benefit-body p{
    min-width:0!important;
  }
  .benefit-body h3{
    line-height:1.3!important;
    overflow:visible!important;
  }
  .benefit-body p{
    line-height:1.45!important;
    overflow:visible!important;
  }
  .employee-section-head h2,
  .employee-section-head p,
  .page-head h1,
  .page-head p{
    overflow-wrap:anywhere!important;
  }

  /* =========================================================
     MENU BOCZNE — stała pozycja i brak „skakania”
     ========================================================= */
  .sidebar{
    overflow:hidden!important;
  }
  .sidebar-menu{
    overflow-y:auto!important;
    overflow-x:hidden!important;
    scrollbar-gutter:stable!important;
    overscroll-behavior:contain!important;
    scroll-behavior:auto!important;
    padding:10px 10px 18px!important;
  }
  .menu-btn{
    box-sizing:border-box!important;
    flex:0 0 auto!important;
    width:100%!important;
    min-height:44px!important;
    height:auto!important;
    margin:2px 0!important;
    padding:9px 10px!important;
    line-height:1.25!important;
    overflow:visible!important;
  }
  .menu-btn > span:not(.count){
    min-width:0!important;
    white-space:normal!important;
    overflow:visible!important;
    text-overflow:clip!important;
    line-height:1.25!important;
  }
  .menu-btn .count{
    flex:0 0 auto!important;
  }
  .menu-btn.active{
    transform:none!important;
  }
  .sidebar-context b,
  .sidebar-context span,
  .menu-group-label{
    overflow-wrap:anywhere!important;
    line-height:1.3!important;
  }

  /* Stabilniejsza szerokość treści i brak poziomego ucinania */
  .main-content{
    overflow-x:hidden!important;
  }
  .view-container{
    min-width:0!important;
  }

  @media(max-width:1280px){
    .employee-catalog-controls{
      grid-template-columns:minmax(280px,1fr) minmax(165px,195px) minmax(165px,195px)!important;
    }
    .employee-catalog-controls .filter-favorite,
    .employee-catalog-controls .secondary-btn{
      width:auto!important;
    }
  }
  @media(max-width:900px){
    .employee-catalog-controls{
      grid-template-columns:1fr 1fr!important;
    }
    .employee-catalog-controls .search{
      grid-column:1/-1!important;
    }
  }
  @media(max-width:620px){
    .employee-catalog-controls{
      grid-template-columns:1fr!important;
    }
    .employee-catalog-controls .search{
      grid-column:auto!important;
    }
    .employee-catalog-controls > *{
      width:100%!important;
    }
    .v15-category-wrap,
    .category-scroll{
      gap:6px!important;
    }
    .v15-category-chip,
    .category-chip{
      min-height:36px!important;
      padding:7px 10px!important;
