/* 026 — ub-v33-personalized-card-shop-style */
/* =========================================================
     PERSONALIZOWANY SKLEP KART — wyeksponowany, ale nie nachalny
     ========================================================= */
  .v33-gift-spotlight{
    position:relative;
    display:grid;
    grid-template-columns:minmax(0,1.2fr) minmax(300px,.8fr);
    gap:24px;
    align-items:center;
    width:100%;
    margin:22px 0 24px;
    padding:clamp(22px,3vw,34px);
    border-radius:24px;
    overflow:hidden;
    color:#fff;
    background:
      radial-gradient(circle at 92% 8%,rgba(255,255,255,.17) 0 13%,transparent 13.5%),
      radial-gradient(circle at 86% 90%,rgba(255,255,255,.09) 0 18%,transparent 18.5%),
      linear-gradient(135deg,#51133f 0%,#78195d 56%,#9a4b88 100%);
    box-shadow:0 18px 45px rgba(76,18,57,.16);
  }
  .v33-gift-spotlight:before{
    content:"";
    position:absolute;
    inset:0;
    pointer-events:none;
    background:linear-gradient(115deg,rgba(255,255,255,.08),transparent 35%);
  }
  .v33-gift-copy,
  .v33-gift-visual{
    position:relative;
    z-index:1;
    min-width:0;
  }
  .v33-gift-kicker{
    display:inline-flex;
    align-items:center;
    gap:7px;
    margin-bottom:10px;
    font-size:10px;
    font-weight:900;
    letter-spacing:.11em;
    text-transform:uppercase;
    color:#ffd7f0;
  }
  .v33-gift-copy h2{
    max-width:760px;
    margin:0;
    font-size:clamp(27px,3vw,43px);
    line-height:1.04;
    letter-spacing:-.03em;
    color:#fff;
  }
  .v33-gift-copy>p{
    max-width:720px;
    margin:13px 0 0;
    font-size:13px;
    line-height:1.65;
    color:rgba(255,255,255,.84);
  }
  .v33-gift-points{
    display:flex;
    flex-wrap:wrap;
    gap:7px;
    margin-top:17px;
  }
  .v33-gift-points span{
    display:inline-flex;
    align-items:center;
    min-height:31px;
    padding:6px 10px;
    border:1px solid rgba(255,255,255,.18);
    border-radius:999px;
    background:rgba(255,255,255,.10);
    color:#fff;
    font-size:10px;
    font-weight:750;
    backdrop-filter:blur(7px);
  }
  .v33-gift-actions{
    display:flex;
    flex-wrap:wrap;
    gap:10px;
    margin-top:21px;
  }
  .v33-gift-actions button{
    min-height:45px;
    padding:10px 17px;
    border-radius:13px;
    font-weight:850;
    cursor:pointer;
  }
  .v33-gift-actions .v33-primary{
    border:1px solid #fff;
    background:#fff;
    color:#6b174e;
  }
  .v33-gift-actions .v33-secondary{
    border:1px solid rgba(255,255,255,.32);
    background:rgba(255,255,255,.08);
    color:#fff;
  }

  /* Wizualizacja trzech przykładowych kart */
  .v33-gift-visual{
    min-height:210px;
    display:grid;
    place-items:center;
    perspective:1000px;
  }
  .v33-card-mock{
    position:absolute;
    width:min(280px,72%);
    aspect-ratio:1.58/1;
    border-radius:19px;
    overflow:hidden;
    border:1px solid rgba(255,255,255,.42);
    box-shadow:0 20px 38px rgba(31,7,25,.28);
    transform-origin:center;
  }
  .v33-card-mock:before{
    content:"";
    position:absolute;
    inset:0;
    background:linear-gradient(120deg,rgba(255,255,255,.22),transparent 34%);
    pointer-events:none;
  }
  .v33-card-a{
    z-index:3;
    transform:translate(8px,5px) rotate(-2deg);
    background:linear-gradient(135deg,#ff7a00,#ff9e2d);
  }
  .v33-card-b{
    z-index:2;
    transform:translate(-42px,-31px) rotate(-9deg);
    background:linear-gradient(135deg,#f7d8eb,#b96da5);
  }
  .v33-card-c{
    z-index:1;
    transform:translate(45px,39px) rotate(8deg);
    background:linear-gradient(135deg,#6c4fa0,#3c245f);
  }
  .v33-card-content{
    position:absolute;
    inset:0;
    display:flex;
    flex-direction:column;
    justify-content:space-between;
    padding:18px;
    color:#fff;
  }
  .v33-card-logo{
    display:flex;
    align-items:center;
    gap:8px;
    font-size:11px;
    font-weight:900;
  }
  .v33-card-logo i{
    width:27px;
    height:27px;
    display:grid;
    place-items:center;
    border-radius:9px;
    background:rgba(255,255,255,.92);
    color:#7b1754;
    font-style:normal;
  }
  .v33-card-message{
    max-width:80%;
    font-size:15px;
    font-weight:900;
    line-height:1.15;
  }
  .v33-card-foot{
    display:flex;
    justify-content:space-between;
    gap:8px;
    font-size:8px;
    font-weight:750;
    letter-spacing:.04em;
    text-transform:uppercase;
    color:rgba(255,255,255,.78);
  }

  /* Kompaktowa wersja na pulpitach */
  .v33-gift-spotlight.compact{
    grid-template-columns:minmax(0,1fr) 250px;
    margin:18px 0;
    padding:21px 24px;
    border-radius:20px;
  }
  .v33-gift-spotlight.compact .v33-gift-copy h2{
    font-size:clamp(22px,2.3vw,31px);
  }
  .v33-gift-spotlight.compact .v33-gift-copy>p{
    font-size:11px;
  }
  .v33-gift-spotlight.compact .v33-gift-visual{
    min-height:165px;
  }
  .v33-gift-spotlight.compact .v33-card-mock{
    width:195px;
    border-radius:15px;
  }
  .v33-gift-spotlight.compact .v33-card-content{
    padding:13px;
  }
  .v33-gift-spotlight.compact .v33-card-message{
    font-size:11px;
  }

  /* Strona dedykowana sklepowi */
  .v33-shop-intro{
    margin-bottom:22px;
  }
  .v33-shop-grid{
    display:grid;
    grid-template-columns:repeat(3,minmax(0,1fr));
    gap:13px;
    margin-bottom:20px;
  }
  .v33-shop-feature{
    min-height:170px;
    padding:18px;
    border:1px solid var(--brand-border);
    border-radius:18px;
    background:#fff;
  }
  .v33-shop-feature i{
    width:42px;
    height:42px;
    display:grid;
    place-items:center;
    margin-bottom:13px;
    border-radius:13px;
    background:var(--brand-soft);
    font-size:20px;
    font-style:normal;
  }
  .v33-shop-feature h3{
    margin:0 0 7px;
    font-size:16px;
  }
  .v33-shop-feature p{
    margin:0;
    color:var(--brand-muted);
    font-size:11px;
    line-height:1.55;
  }
  .v33-process{
    display:grid;
    grid-template-columns:repeat(4,minmax(0,1fr));
    gap:9px;
    margin-top:12px;
  }
  .v33-process article{
    padding:14px;
    border:1px solid var(--brand-border);
    border-radius:15px;
    background:#fff;
  }
  .v33-process b{
    display:block;
    margin-bottom:5px;
    font-size:11px;
  }
  .v33-process span{
    display:block;
    color:var(--brand-muted);
    font-size:9px;
    line-height:1.45;
  }
  .v33-process strong{
    display:grid;
    place-items:center;
    width:28px;
    height:28px;
    margin-bottom:9px;
    border-radius:9px;
    background:var(--brand-primary);
    color:#fff;
    font-size:11px;
  }
  .v33-orders{
    margin-top:20px;
    padding:17px;
    border:1px solid var(--brand-border);
    border-radius:18px;
    background:#fff;
  }
  .v33-orders-head{
    display:flex;
    justify-content:space-between;
    gap:12px;
    align-items:flex-start;
    margin-bottom:12px;
  }
  .v33-orders-head h2{
    margin:0 0 4px;
  }
  .v33-orders-head p{
    margin:0;
    color:var(--brand-muted);
    font-size:10px;
  }
  .v33-orders-table{
    overflow:auto;
    border:1px solid var(--brand-border);
    border-radius:13px;
  }
  .v33-orders-table table{
    width:100%;
    min-width:760px;
    border-collapse:collapse;
  }
  .v33-orders-table th,
  .v33-orders-table td{
    padding:10px 11px;
    border-bottom:1px solid var(--brand-border);
    text-align:left;
    font-size:10px;
  }
  .v33-orders-table th{
    background:#faf7fb;
    color:var(--brand-muted);
    font-size:8px;
    letter-spacing:.07em;
    text-transform:uppercase;
  }

  /* Wyróżniony link w menu */
  .v33-shop-menu{
    position:relative;
    margin-top:4px!important;
    border:1px solid #ead2e2!important;
    background:linear-gradient(90deg,#fff9fc,#f8eef6)!important;
  }
  .v33-shop-menu:after{
    content:"Nowość";
    margin-left:auto;
    padding:3px 6px;
    border-radius:999px;
    background:#7b1754;
    color:#fff;
    font-size:7px;
    font-weight:900;
    letter-spacing:.05em;
    text-transform:uppercase;
  }
  .v33-shop-menu.active{
    color:var(--brand-primary)!important;
    border-color:#c78eaf!important;
    box-shadow:inset 3px 0 0 var(--brand-primary)!important;
  }

  @media(max-width:1050px){
    .v33-gift-spotlight,
    .v33-gift-spotlight.compact{
      grid-template-columns:1fr 245px;
    }
    .v33-shop-grid{
      grid-template-columns:repeat(2,minmax(0,1fr));
    }
    .v33-process{
      grid-template-columns:repeat(2,minmax(0,1fr));
    }
  }
  @media(max-width:760px){
    .v33-gift-spotlight,
    .v33-gift-spotlight.compact{
      grid-template-columns:1fr;
      gap:17px;
      padding:21px;
    }
    .v33-gift-visual,
    .v33-gift-spotlight.compact .v33-gift-visual{
      min-height:205px;
    }
    .v33-shop-grid{
      grid-template-columns:1fr;
    }
  }
  @media(max-width:560px){
    .v33-gift-spotlight{
      margin:15px 0 18px;
      border-radius:18px;
    }
    .v33-gift-copy h2{
      font-size:27px;
    }
    .v33-gift-actions>*{
      width:100%;
    }
    .v33-process{
      grid-template-columns:1fr;
    }
    .v33-card-mock{
      width:220px;
    }
    .v33-card-b{
      transform:translate(-29px,-25px) rotate(-8deg);
    }
    .v33-card-c{
      transform:translate(30px,31px) rotate(7deg);
    }
  }

/* 027 — ub-v34-unified-admin-style */
.v34-account-topbar{
    min-height:72px;
    display:flex;
