  .v34-access-tags{
    display:flex;
    flex-wrap:wrap;
    gap:5px;
    margin-top:13px;
  }
  .v34-access-tags span{
    padding:4px 7px;
    border-radius:999px;
    background:#f7f2f7;
    color:#6c5c67;
