  .v34-admin-quick{
    display:grid;
    grid-template-columns:repeat(4,minmax(0,1fr));
    gap:10px;
  }
  .v34-admin-quick button{
    min-height:135px;
    padding:15px;
    border:1px solid var(--brand-border);
    border-radius:16px;
    background:#fff;
    text-align:left;
    cursor:pointer;
