  .v34-admin-quick button:hover{border-color:#c79ab5;background:#fdf9fc}
  .v34-admin-quick i{
    width:52px;
    height:52px;
    display:grid;
    place-items:center;
    margin-bottom:12px;
    border-radius:16px;
    background:var(--brand-soft);
    font-style:normal;
    font-size:24px;
