  .v34-admin-quick b,
  .v34-admin-quick span{display:block}
  .v34-admin-quick b{font-size:12px}
  .v34-admin-quick span{
    margin-top:5px;
    color:var(--brand-muted);
    font-size:9px;
    line-height:1.4;
  }

  @media(max-width:1120px){
    .v34-access-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
    .v34-admin-quick{grid-template-columns:repeat(2,minmax(0,1fr))}
  }
  @media(max-width:760px){
    .v34-account-topbar{padding-inline:12px}
    .v34-account-brand small{display:none}
    .v34-account-profile>span{display:none}
    .v34-account-profile{padding-right:6px}
    .v34-account-hero{grid-template-columns:1fr;padding:24px}
    .v34-hero-avatar{grid-row:1;justify-self:start;width:94px;height:94px;border-radius:24px}
