/* 030 — ub-v38-shop-category-menu-style */
/* =========================================================
     KATEGORIE KATALOGU — jeden zwarty pasek + rozwijany katalog
     ========================================================= */
  .v38-category-toolbar{
    position:relative;
    display:flex;
    align-items:center;
    gap:8px;
    width:100%;
    margin:4px 0 16px;
    padding:0;
  }
  .v38-category-primary{
    display:flex;
    align-items:center;
    gap:7px;
    flex:1 1 auto;
    min-width:0;
    overflow-x:auto;
    overflow-y:hidden;
    padding:2px 1px 5px;
    scrollbar-width:none;
    overscroll-behavior-x:contain;
  }
  .v38-category-primary::-webkit-scrollbar{display:none}
  .v38-category-chip,
  .v38-category-more>summary{
    display:inline-flex;
    align-items:center;
    justify-content:center;
    gap:6px;
    flex:0 0 auto;
    min-height:38px;
    padding:8px 12px;
    border:1px solid var(--brand-border);
    border-radius:999px;
    background:#fff;
    color:var(--brand-ink);
    font-size:10px;
    font-weight:850;
    line-height:1.15;
    white-space:nowrap;
    cursor:pointer;
  }
  .v38-category-chip:hover,
  .v38-category-more>summary:hover{
    border-color:var(--brand-accent);
    background:var(--brand-soft);
    color:var(--brand-primary);
  }
  .v38-category-chip.active{
    border-color:var(--brand-primary);
    background:var(--brand-primary);
    color:#fff;
  }
  .v38-category-more{
    position:relative;
    flex:0 0 auto;
  }
  .v38-category-more>summary{
    list-style:none;
    min-width:155px;
  }
  .v38-category-more>summary::-webkit-details-marker{display:none}
  .v38-category-more>summary:after{
    content:'⌄';
    margin-left:3px;
    font-size:13px;
    line-height:1;
  }
  .v38-category-more[open]>summary{
    border-color:var(--brand-primary);
    color:var(--brand-primary);
    box-shadow:0 0 0 3px rgba(123,23,84,.07);
  }
  .v38-category-panel{
    position:absolute;
    z-index:60;
    top:calc(100% + 9px);
    right:0;
    width:min(720px,calc(100vw - 64px));
    max-height:min(560px,68vh);
    overflow:auto;
    padding:16px;
    border:1px solid var(--brand-border);
    border-radius:18px;
    background:#fff;
    box-shadow:0 22px 55px rgba(54,20,44,.18);
  }
  .v38-category-panel-head{
    display:flex;
    align-items:flex-start;
    justify-content:space-between;
    gap:12px;
    margin-bottom:12px;
  }
  .v38-category-panel-head h3{
    margin:0 0 3px;
    font-size:16px;
  }
  .v38-category-panel-head p{
    margin:0;
    color:var(--brand-muted);
    font-size:9px;
    line-height:1.4;
  }
  .v38-category-search{
    position:relative;
    margin-bottom:13px;
  }
  .v38-category-search span{
    position:absolute;
    left:12px;
    top:50%;
    transform:translateY(-50%);
    color:var(--brand-muted);
    pointer-events:none;
  }
  .v38-category-search input{
    box-sizing:border-box;
    width:100%;
    min-height:42px;
    padding:8px 12px 8px 37px;
    border:1px solid var(--brand-border);
    border-radius:12px;
    background:#fff;
    color:var(--brand-ink);
    font:inherit;
    font-size:11px;
  }
  .v38-category-groups{
    display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:12px;
  }
  .v38-category-group{
    min-width:0;
    padding:12px;
    border:1px solid var(--brand-border);
    border-radius:14px;
    background:#fcfafc;
  }
  .v38-category-group h4{
    margin:0 0 9px;
    color:var(--brand-muted);
    font-size:8px;
    font-weight:900;
    letter-spacing:.08em;
    text-transform:uppercase;
  }
  .v38-category-options{
    display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:6px;
  }
  .v38-category-option{
    display:flex;
    align-items:center;
    gap:7px;
    min-width:0;
    min-height:39px;
    padding:8px 9px;
    border:1px solid transparent;
    border-radius:10px;
    background:#fff;
    color:var(--brand-ink);
    text-align:left;
    cursor:pointer;
  }
  .v38-category-option:hover{
    border-color:var(--brand-accent);
    background:var(--brand-soft);
  }
  .v38-category-option.active{
    border-color:var(--brand-primary);
    background:var(--brand-soft);
    color:var(--brand-primary);
  }
  .v38-category-option span:last-child{
    min-width:0;
    overflow:hidden;
    text-overflow:ellipsis;
    white-space:nowrap;
    font-size:9px;
    font-weight:800;
  }
  .v38-category-empty{
    grid-column:1/-1;
    padding:17px;
    border:1px dashed var(--brand-border);
    border-radius:12px;
    color:var(--brand-muted);
    text-align:center;
    font-size:10px;
  }

  /* Stary wielowierszowy zestaw kategorii jest zastępowany przez v38. */
  .employee-dashboard .v15-category-wrap.v38-replaced{display:none!important}

  @media(max-width:900px){
    .v38-category-toolbar{align-items:stretch}
    .v38-category-more>summary{min-width:135px}
    .v38-category-panel{width:min(660px,calc(100vw - 38px))}
  }
  @media(max-width:680px){
    .v38-category-toolbar{display:block}
    .v38-category-primary{margin-bottom:7px}
    .v38-category-more{width:100%}
    .v38-category-more>summary{width:100%;box-sizing:border-box}
    .v38-category-panel{
      position:fixed;
      top:76px;
      right:10px;
      left:10px;
      width:auto;
      max-height:calc(100vh - 96px);
    }
    .v38-category-groups{grid-template-columns:1fr}
  }
  @media(max-width:480px){
    .v38-category-options{grid-template-columns:1fr}
    .v38-category-chip,.v38-category-more>summary{min-height:36px;padding:7px 10px;font-size:9px}
  }

/* 031 — ub-v39-role-switch-style */
.v39-role-switch{
    position:relative;
    display:flex;
    align-items:center;
    gap:8px;
    height:42px;
    max-width:220px;
    padding:4px 10px 4px 7px;
    border:1px solid var(--brand-border);
    border-radius:13px;
    background:#fff;
    color:var(--brand-ink);
    cursor:pointer;
  }
  .v39-role-switch:hover{background:var(--brand-soft)}
  .v39-role-switch-icon{
    width:30px;height:30px;display:grid;place-items:center;
    flex:0 0 30px;border-radius:10px;background:var(--brand-soft);
    color:var(--brand-primary);font-size:15px;font-weight:900;
  }
  .v39-role-switch-copy{min-width:0;text-align:left}
  .v39-role-switch-copy small,
  .v39-role-switch-copy b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
  .v39-role-switch-copy small{font-size:8px;color:var(--brand-muted);line-height:1.1}
  .v39-role-switch-copy b{font-size:10px;line-height:1.2;margin-top:2px}
  .v39-role-switch-chevron{margin-left:auto;color:var(--brand-muted);font-size:12px}

  .v39-role-popover{
    position:fixed;z-index:99999;width:min(340px,calc(100vw - 24px));
    padding:9px;border:1px solid var(--brand-border);border-radius:17px;
    background:#fff;box-shadow:0 20px 48px rgba(41,19,34,.18);
  }
  .v39-role-popover-head{padding:7px 8px 9px}
  .v39-role-popover-head b{display:block;font-size:12px}
  .v39-role-popover-head span{display:block;margin-top:3px;color:var(--brand-muted);font-size:9px;line-height:1.4}
  .v39-role-option{
    width:100%;display:grid;grid-template-columns:38px minmax(0,1fr) auto;
    gap:9px;align-items:center;padding:9px;border:0;border-radius:12px;
    background:#fff;text-align:left;cursor:pointer;
  }
  .v39-role-option:hover{background:var(--brand-soft)}
  .v39-role-option.active{background:#f7edf4;color:var(--brand-primary)}
  .v39-role-option-icon{width:38px;height:38px;display:grid;place-items:center;border-radius:12px;background:var(--brand-soft);font-size:18px}
  .v39-role-option-copy{min-width:0}
  .v39-role-option-copy b,.v39-role-option-copy span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
  .v39-role-option-copy b{font-size:11px}
  .v39-role-option-copy span{margin-top:2px;color:var(--brand-muted);font-size:8px}
  .v39-role-option-mark{color:#15815e;font-size:12px;font-weight:900}
  .v39-role-popover-foot{margin-top:6px;padding-top:7px;border-top:1px solid var(--brand-border)}
  .v39-role-center{
    width:100%;min-height:40px;border:1px solid var(--brand-border);border-radius:11px;
    background:#fff;color:var(--brand-primary);font-weight:850;cursor:pointer;
  }
  .v39-role-center:hover{background:var(--brand-soft)}
  .v39-profile-switch{
    display:flex;align-items:center;justify-content:space-between;gap:10px;
    margin-top:12px;padding:11px 12px;border:1px solid var(--brand-border);
    border-radius:13px;background:#faf8fb;
  }
  .v39-profile-switch span{min-width:0}
  .v39-profile-switch b,.v39-profile-switch small{display:block}
  .v39-profile-switch b{font-size:11px}
  .v39-profile-switch small{margin-top:2px;color:var(--brand-muted);font-size:8px}
  .v39-profile-switch button{flex:0 0 auto}

  @media(max-width:1180px){
    .v39-role-switch{max-width:150px}
    .v39-role-switch-copy small{display:none}
  }
  @media(max-width:860px){
    .v39-role-switch{width:42px;padding:5px;justify-content:center}
    .v39-role-switch-copy,.v39-role-switch-chevron{display:none}
    .v39-role-switch-icon{width:30px;height:30px}
  }

/* 032 — ub-v40-usability-reporting-settlements-style */
