/* wspólne kompaktowe widoki tabel */
.v49-toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:0 0 10px}.v49-toolbar .v49-search{position:relative;flex:1;min-width:250px}.v49-toolbar .v49-search span{position:absolute;left:12px;top:50%;transform:translateY(-50%);display:grid;place-items:center;width:18px;color:var(--brand-muted);pointer-events:none}.v49-toolbar .v49-search input{width:100%;height:40px;border:1px solid var(--brand-border);border-radius:11px;padding:0 12px 0 42px;background:#fff}.v49-toolbar select{height:40px;border:1px solid var(--brand-border);border-radius:11px;padding:0 10px;background:#fff}
.v49-table-wrap{border:1px solid var(--brand-border);border-radius:15px;overflow:auto;background:#fff}.v49-table{width:100%;min-width:980px;border-collapse:collapse}.v49-table th,.v49-table td{padding:8px 10px;border-bottom:1px solid var(--brand-border);text-align:left;vertical-align:middle;font-size:9px}.v49-table th{background:#faf8fb;font-size:8px;text-transform:uppercase;letter-spacing:.045em;position:sticky;top:0;z-index:1;white-space:nowrap}.v49-table td b{font-size:10px}.v49-table td small{display:block;font-size:8px;color:var(--brand-muted);margin-top:2px}.v49-table tbody tr:hover{background:#fdfafd}.v49-table .actions{display:flex;gap:7px;flex-wrap:wrap}.v49-table .actions button{border:0;background:none;color:var(--brand-primary);font-size:9px;font-weight:850;padding:2px 0;cursor:pointer}.v49-table .actions .danger{color:#b4233b}
.v49-chip{display:inline-flex;align-items:center;padding:4px 7px;border-radius:999px;font-size:8px;font-weight:850;background:#f2edf2;color:#5f4f5c;margin:1px 3px 1px 0}.v49-chip.green{background:#e7f7f0;color:#087552}.v49-chip.amber{background:#fff0d3;color:#976000}.v49-chip.red{background:#ffe9ec;color:#b22139}.v49-chip.purple{background:#f4eaf2;color:#741653}
.v49-card{background:#fff;border:1px solid var(--brand-border);border-radius:16px;padding:13px;margin-bottom:12px}.v49-card h2,.v49-card h3{margin:0}.v49-card>p{margin:4px 0 10px;color:var(--brand-muted);font-size:9px;line-height:1.45}
.v49-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin-bottom:11px}.v49-kpi{background:#fff;border:1px solid var(--brand-border);border-radius:14px;padding:11px}.v49-kpi span{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.05em;color:var(--brand-muted);font-weight:850}.v49-kpi b{display:block;font-size:18px;margin-top:5px}.v49-kpi small{display:block;margin-top:3px;font-size:8px;color:var(--brand-muted)}

