/* Up Bonus brand system — isolated visual layer (stage 5).
   Product UI: TT Commons Pro. Brand palette: #490F30 / #FF8500.
   Semantic success, warning and danger colors intentionally remain unchanged. */

:root{
  --ub-font:"TT Commons Pro","Roboto",ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  --ub-plum:#490F30;
  --ub-orange:#FF8500;
  --ub-plum-soft:rgba(73,15,48,.08);
  --ub-orange-soft:rgba(255,133,0,.12);
}

html,body,button,input,select,textarea,
h1,h2,h3,h4,h5,h6,p,span,a,label,small,strong,b,li,td,th{
  font-family:var(--font,var(--ub-font))!important;
}
#ubDeployPreboot,#ubBootFallback{font-family:var(--font,var(--ub-font))!important}
#ubDeployPreboot>div>div:first-child,
#ubBootFallback>div>div:first-child{color:var(--ub-plum)!important}

/* Up Bonus: canonical brand tokens. */
html[data-ub-brand="upbonus"]{
  --brand-primary:var(--ub-plum)!important;
  --brand-primary-2:var(--ub-plum)!important;
  --brand-accent:var(--ub-orange)!important;
  --brand-soft:var(--ub-plum-soft)!important;
  --brand-bg:#fff!important;
  --brand-surface:#fff!important;
  --brand-text:#000!important;
  --brand-muted:#51454c!important;
  --brand-border:rgba(73,15,48,.20)!important;
  --v91-active-bg:var(--ub-plum-soft)!important;
  --v91-active-text:var(--ub-plum)!important;
  --v91-banner-start:var(--ub-plum)!important;
  --v91-banner-end:var(--ub-orange)!important;
  --v91-button-bg:var(--ub-plum)!important;
  --v91-button-text:#fff!important;
}

html[data-ub-brand="upbonus"] :is(.primary-btn,.compact-btn.primary,.ub64-actions button.primary){
  background:var(--ub-plum)!important;
  border-color:var(--ub-plum)!important;
  color:#fff!important;
}
html[data-ub-brand="upbonus"] :is(.link-btn,.ghost-btn,.v107-action){color:var(--ub-plum)!important}
html[data-ub-brand="upbonus"] :is(input,select,textarea,[contenteditable="true"]):focus{
