}
html[data-ub-brand="upbonus"] :is(.menu-btn,.v589-emp-item):hover{
  background:var(--ub-orange-soft)!important;
}
html[data-ub-brand="upbonus"] :is(.menu-btn,.v589-emp-item).active :is(svg,b,span,small){color:#fff!important}

html[data-ub-brand="upbonus"] :is(
