html[data-ub-brand="upbonus"] :is(.hero-main,.employee-hero,.employee-banner,.login-brand,.v14-ewallet-main,.v20-hero,.v56-gift-panel,.v59-content-preview,.v103-hero,.v107-hero) :is(h1,h2,h3,h4,p,span,b,strong,small,a){color:#fff!important}

