/* ===== SOURCE: upbonus-architecture-v18.css ===== */
/* Up Bonus v15 — commerce-first dashboard */
:root{
  --ub13-wine:#5b103d;
  --ub13-wine-2:#7b1455;
  --ub13-orange:#ff8500;
  --ub13-ink:#211722;
  --ub13-muted:#756c76;
  --ub13-line:#e6dce6;
  --ub13-bg:#f7f5f8;
  --ub13-soft:#fbf8fb;
}

/* Employee navigation: stable, compact, need-based */

/* Architecture screens */
.ub13-page{display:grid;gap:14px;max-width:1180px;margin:0 auto;padding-bottom:28px}
.ub13-hero{
  display:grid;grid-template-columns:minmax(0,1.45fr) minmax(250px,.55fr);gap:16px;
  border:1px solid #e5d9e3;background:linear-gradient(135deg,#fff 0%,#fcf7fb 100%);
  border-radius:20px;padding:24px;box-shadow:0 10px 28px rgba(60,30,55,.06)
}
.ub13-kicker{font-size:10px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--ub13-orange)}
.ub13-hero h1{font-size:30px;line-height:1.08;margin:6px 0 8px;color:var(--ub13-ink)}
.ub13-hero p{margin:0;color:var(--ub13-muted);font-size:13px;line-height:1.55}
.ub13-hero-card{background:var(--ub13-wine);color:#fff;border-radius:16px;padding:18px;display:flex;flex-direction:column;justify-content:center;min-height:132px}
.ub13-hero-card span{font-size:11px;opacity:.78}.ub13-hero-card strong{font-size:27px;margin:4px 0 10px}.ub13-hero-card button{align-self:flex-start}
.ub13-hero-card.is-benefits{background:linear-gradient(135deg,#5b103d,#7d1758)}
.ub13-hero-card .ub13-light-btn{border:0;background:#fff;color:var(--ub13-wine);font-weight:750;padding:9px 12px;border-radius:10px;cursor:pointer}

.ub13-campaign{border-radius:18px;padding:20px 22px;color:#fff;background:linear-gradient(120deg,#4c0d35 0%,#70134f 55%,#8c1c62 100%);position:relative;overflow:hidden}
.ub13-campaign::after{content:"";position:absolute;width:180px;height:180px;border:28px solid rgba(255,255,255,.09);border-radius:50%;right:-45px;top:-62px}
.ub13-campaign h2{margin:5px 0;font-size:21px}.ub13-campaign p{margin:0 0 12px;opacity:.83;font-size:12px}.ub13-campaign button{border:0;border-radius:10px;padding:9px 12px;font-weight:750;background:var(--ub13-orange);color:#281628;cursor:pointer}

.ub13-section{background:#fff;border:1px solid var(--ub13-line);border-radius:18px;padding:18px}
.ub13-section-head{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;margin-bottom:13px}
.ub13-section-head h2{font-size:19px;margin:0;color:var(--ub13-ink)}
.ub13-section-head p{font-size:11px;color:var(--ub13-muted);margin:4px 0 0}
.ub13-link-btn{border:0;background:transparent;color:var(--ub13-wine);font-size:11px;font-weight:750;cursor:pointer}

.ub13-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px}
.ub13-grid[data-count="3"]{grid-template-columns:repeat(2,minmax(0,1fr))}
.ub13-grid[data-count="3"] .ub13-tile:last-child{grid-column:1/-1}
.ub13-grid[data-count="5"] .ub13-tile:first-child{grid-column:1/-1}
.ub13-tile{border:1px solid #eadfe8;border-radius:14px;padding:15px;background:#fff;min-height:118px;display:flex;flex-direction:column;gap:8px;cursor:pointer;transition:.18s ease}
.ub13-tile:hover{transform:translateY(-1px);box-shadow:0 8px 18px rgba(58,27,53,.07);border-color:#d9c4d4}
.ub13-tile-icon{width:36px;height:36px;border-radius:11px;display:grid;place-items:center;background:#f9eff6;font-size:18px}
.ub13-tile h3{font-size:14px;margin:0;color:var(--ub13-ink)}.ub13-tile p{font-size:11px;line-height:1.4;color:var(--ub13-muted);margin:0}.ub13-tile small{margin-top:auto;font-size:10px;font-weight:750;color:var(--ub13-wine)}
.ub13-chip{display:inline-flex;align-items:center;width:max-content;gap:5px;border-radius:999px;padding:5px 8px;font-size:9px;font-weight:800;background:#f6edf4;color:var(--ub13-wine)}
.ub13-chip.orange{background:#fff1e0;color:#a44d00}
.ub13-chip.green{background:#eaf8f2;color:#147250}

.ub13-quick{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}
.ub13-quick-card{border:1px solid #eadfe8;border-radius:14px;padding:14px;background:var(--ub13-soft);display:flex;align-items:center;gap:10px;cursor:pointer}
.ub13-quick-card b{display:block;font-size:12px}.ub13-quick-card span{font-size:10px;color:var(--ub13-muted)}

.ub13-empty-smart{border:1px dashed #d7c7d2;border-radius:14px;padding:18px;text-align:center;background:#fcfafc}.ub13-empty-smart b{font-size:14px}.ub13-empty-smart p{font-size:11px;color:var(--ub13-muted);margin:5px 0 0}

