.ub13-client-select{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.ub13-client-select select{min-width:260px;border:1px solid #ddced9;border-radius:10px;padding:9px 11px;background:#fff}
.ub13-package-tabs{display:flex;gap:7px;flex-wrap:wrap}.ub13-package-btn{border:1px solid #dccbd8;background:#fff;color:#4a3947;border-radius:10px;padding:9px 12px;font-weight:750;cursor:pointer}.ub13-package-btn.active{background:var(--ub13-wine);color:#fff;border-color:var(--ub13-wine)}
