.ub66-case-data dl{display:grid;grid-template-columns:1fr 1.1fr;gap:6px 10px;margin:0}.ub66-case-data dt{color:#887a82;font-size:9px}.ub66-case-data dd{margin:0;color:#3e2934;font-size:10px;font-weight:700;overflow-wrap:anywhere}
