.ub66-messages{display:grid;gap:7px;max-height:360px;overflow:auto}.ub66-messages article{max-width:88%;padding:10px 11px;border-radius:12px;background:#f8f4f6}.ub66-messages article.bok{margin-left:auto;background:#f1e6ed}.ub66-messages article.internal{background:#fff4e8;border:1px dashed #e5c79c}.ub66-messages article.partner{background:#eef3fa}.ub66-messages article>div{display:flex;justify-content:space-between;gap:8px}.ub66-messages b{font-size:10px}.ub66-messages time{font-size:8px;color:#8b7c85}.ub66-messages p{margin:4px 0 0;font-size:10px;line-height:1.4}
.ub66-message-form{display:grid;gap:8px;margin-top:10px;padding-top:10px;border-top:1px solid #eee5ea}.ub66-message-toggle{display:flex;gap:7px}.ub66-message-toggle input{position:absolute;opacity:0}.ub66-message-toggle span{display:block;padding:6px 9px;border:1px solid #dfd2da;border-radius:999px;font-size:9px;cursor:pointer}.ub66-message-toggle input:checked+span{background:#f1e3eb;border-color:#cda9bd;color:#490F30;font-weight:900}.ub66-message-form textarea{width:100%;box-sizing:border-box;border:1px solid #ddcfd7;border-radius:10px;padding:9px;font:inherit;resize:vertical}.ub66-message-form>div:last-child{display:flex;justify-content:space-between;gap:8px}.ub66-message-form select{border:1px solid #ddcfd7;border-radius:9px;background:#fff;padding:7px 8px;font-size:10px}
.ub66-case-actions{display:grid;gap:9px}.ub66-case-actions .ub66-panel{display:grid;gap:7px}.ub66-case-actions h2{margin:0 0 4px;font-size:15px;color:#3b1a2b}.ub66-case-actions button{width:100%;border:1px solid #ddcfd7;border-radius:9px;background:#fff;padding:8px 9px;color:#492437;font-weight:800;cursor:pointer}.ub66-case-actions .ub66-action-primary{background:#490F30;border-color:#490F30;color:#fff}.ub66-case-actions .ub66-action-danger{color:#a02e37;border-color:#e4b9bd;background:#fff8f8}.ub66-secondary-actions{display:grid;gap:4px;margin-top:3px;padding-top:7px;border-top:1px solid #eee5ea}.ub66-secondary-actions button{border:0;background:transparent;text-align:left;padding:5px 2px;font-size:10px;font-weight:600;color:#70606a}
