/* ==========================================================
   UP BONUS V153 — PRESENTATION HARDENING
   Final typography, 100% zoom readability, responsive scale,
   larger icons, product media consistency, removal of prototype notes.
========================================================== */
:root{
  --ub-font-ui:"Inter","Segoe UI",Roboto,Arial,sans-serif;
  --ub-fs-10:10px;
  --ub-fs-11:11px;
  --ub-fs-12:12px;
  --ub-fs-13:13px;
  --ub-fs-14:14px;
  --ub-fs-15:15px;
  --ub-fs-16:16px;
  --ub-fs-18:18px;
  --ub-fs-20:20px;
  --ub-fs-24:24px;
  --ub-fs-30:30px;
  --ub-fs-34:34px;
  --ub-line-body:1.48;
  --ub-ink:#2f1a28;
  --ub-muted:#756a73;
}

/* One UI font across every role and every auth state. */
html,body,#app,#app *,button,input,select,textarea,table,dialog{
  font-family:var(--ub-font-ui)!important;
  font-stretch:normal!important;
  text-rendering:optimizeLegibility;
  -webkit-font-smoothing:antialiased;
}
html{font-size:16px!important;-webkit-text-size-adjust:100%;text-size-adjust:100%}
body{font-size:var(--ub-fs-14)!important;line-height:var(--ub-line-body)!important;color:var(--ub-ink)!important}
button,input,select,textarea{font-size:var(--ub-fs-14)!important;line-height:1.4!important}

/* Base hierarchy: readable at browser zoom 100%. */
:is(.page-head,.employee-dashboard,.page-content,.modal,.login-box,.v71-login-box,.v34-account-page) h1{
  font-size:clamp(28px,2vw,34px)!important;line-height:1.14!important;font-weight:750!important;letter-spacing:-.025em!important;
}
:is(.page-head,.employee-dashboard,.page-content,.modal,.login-box,.v71-login-box,.v34-account-page) h2{
  font-size:clamp(20px,1.45vw,24px)!important;line-height:1.24!important;font-weight:720!important;letter-spacing:-.015em!important;
}
:is(.employee-dashboard,.page-content,.modal,.card,.panel,.ub15-product-body,.v34-access-card) h3{
