/* ===== SOURCE: upbonus-v226-color-foundation.css ===== */
/* ==========================================================
   UP BONUS V226 — ONE COLOR FOUNDATION FOR THE WHOLE PROJECT
   Built against the user's up-bonus-master-clean-main (6).zip.

   Principle:
   - authored component `color` remains the source of truth,
   - stale `-webkit-text-fill-color` cannot override it anymore,
   - light application surfaces receive a stable dark default,
   - intentional dark components receive explicit light text,
   - no layout / spacing / font-size changes.
========================================================== */

:root{
  --ub226-plum:#5A0B3B;
  --ub226-plum-dark:#2F0B22;
  --ub226-orange:#FF8500;
  --ub226-text:#34232E;
  --ub226-heading:#4B1234;
  --ub226-muted:#786671;
  --ub226-soft:#F8F3F6;
}

/* ==========================================================
   GLOBAL TEXT-FILL NORMALIZATION
   This is the core blocker removal:
   previous layers left white -webkit-text-fill-color on nodes even when
   their normal CSS `color` was correct. Normalize fill to currentColor.
========================================================== */
:is(
  .main-content,
  .page-content,
  .employee-dashboard,
  .role-app,
  .modal,
  [class*="modal"],
  [class*="drawer"]
) :is(
  h1,h2,h3,h4,h5,h6,p,span,small,b,strong,label,a,button,li,td,th,em
){
  -webkit-text-fill-color:currentColor!important;
  opacity:1;
}

/* Main application content is a light surface by default. */
.main-content,
.page-content,
.employee-dashboard{
  color:var(--ub226-text)!important;
}

/* Stable default hierarchy for every tab / role. */
:is(.main-content,.page-content,.employee-dashboard) :is(h1,h2,h3,h4,h5,h6){
  color:var(--ub226-heading);
}
:is(.main-content,.page-content,.employee-dashboard) :is(p,small){
  color:var(--ub226-muted);
}

/* White cards/panels/tables across employee, HR, BOK, finance, partner, admin. */
:is(.main-content,.page-content) :is(
  .panel,
  [class*="-panel"],
  [class*="-card"],
  [class*="-sheet"],
  [class*="-box"],
  [class*="-table-wrap"],
  [class*="-toolbar"]
){
  color:var(--ub226-text);
}

/* Inputs always readable on light form controls. */
:is(.main-content,.page-content,.modal,[class*="modal"]) :is(
  input,select,textarea
){
  color:var(--ub226-text)!important;
  -webkit-text-fill-color:var(--ub226-text)!important;
}
:is(.main-content,.page-content,.modal,[class*="modal"]) :is(
  input,textarea
)::placeholder{
  color:#988792!important;
  -webkit-text-fill-color:#988792!important;
  opacity:1!important;
}

/* ==========================================================
   TOPBAR / SIDEBAR — LIGHT
========================================================== */
.topbar,.employee-topbar{
  background:#fff!important;
  color:var(--ub226-text)!important;
}
.topbar :is(button,select,input,a,b,strong,span,small),
.employee-topbar :is(button,select,input,a,b,strong,span,small){
  color:var(--ub226-text);
  -webkit-text-fill-color:currentColor!important;
  opacity:1!important;
}
.sidebar,.sidebar-menu,.sidebar-foot{
  background:#fff!important;
  color:var(--ub226-text)!important;
}
.sidebar :is(button,a,b,strong,span,small){
  -webkit-text-fill-color:currentColor!important;
  opacity:1!important;
}

/* ==========================================================
   LOGIN — LEFT DARK / RIGHT LIGHT
========================================================== */
.v71-login-left,.v69-login-left,.v16-login-left,.login-brand{
  background:linear-gradient(145deg,#731451 0%,#54113F 62%,#35102C 100%)!important;
  color:#fff!important;
}
.v71-login-left :is(h1,h2,h3,h4,p,span,small,b,strong),
