/* ===== SOURCE: upbonus-v228-final-ux.css ===== */
/* ==========================================================
   UP BONUS V228 — FINAL PREMIUM UX
   Communication, HR Reports, topbar containment, footer cleanup.
========================================================== */

:root{
  --v228-plum:#5A0B3B;
  --v228-plum2:#7A1C57;
  --v228-orange:#FF8500;
  --v228-bg:#F7F6F8;
  --v228-text:#2E2530;
  --v228-muted:#746872;
  --v228-border:#E8E1E6;
}

/* ---------- PROFILE / INITIALS: never overflow the viewport ---------- */
.topbar,
.employee-topbar{
  min-width:0!important;
}
.topbar .profile-btn,
.employee-topbar .profile-btn,
[class*="topbar"] .profile-btn{
  max-width:min(250px,24vw)!important;
  min-width:0!important;
  overflow:hidden!important;
  flex:0 1 auto!important;
}
.topbar .profile-btn>span:not(.avatar),
.employee-topbar .profile-btn>span:not(.avatar),
.topbar .profile-btn .copy,
.employee-topbar .profile-btn .copy{
  min-width:0!important;
  overflow:hidden!important;
}
.topbar .profile-btn :is(b,strong,small),
.employee-topbar .profile-btn :is(b,strong,small){
  display:block!important;
  max-width:100%!important;
  white-space:nowrap!important;
  overflow:hidden!important;
  text-overflow:ellipsis!important;
}
@media(max-width:1180px){
  .topbar .profile-btn,
  .employee-topbar .profile-btn{max-width:180px!important}
}
@media(max-width:980px){
  .topbar .profile-btn,
  .employee-topbar .profile-btn{max-width:126px!important}
}

/* ---------- FOOTER: V230 — styling moved to universal footer ---------- */

/* ---------- OPERATIONS: remove only from switch dropdown ---------- */
.ub187-role-menu [data-role="operations"],
.v68-role-menu [data-role="operations"],
.ub185-role-menu [data-role="operations"],
[role="menu"] [data-role="operations"]{
  display:none!important;
}

/* ---------- Shared premium HR ---------- */
.ub228-comms,
.ub228-reports{
  padding:24px 28px 40px!important;
  background:var(--v228-bg)!important;
  color:var(--v228-text)!important;
}
.ub228-hero-row{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:24px;
  margin-bottom:18px;
}
.ub228-hero-row h1{
  margin:2px 0 6px;
  font-size:34px!important;
  line-height:1.05;
  color:#4B1234!important;
}
.ub228-hero-row p{
  margin:0;
  max-width:800px;
  color:var(--v228-muted)!important;
  font-size:14px!important;
}
.ub228-kicker{
  color:var(--v228-orange)!important;
  font-size:11px!important;
  font-weight:900!important;
  letter-spacing:.14em;
}
.ub228-head-actions{
  display:flex;
  gap:8px;
  flex-wrap:wrap;
  justify-content:flex-end;
}
.ub228-kpis{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:12px;
  margin-bottom:14px;
}
.ub228-kpis article{
  background:#fff;
  border:1px solid var(--v228-border);
  border-radius:16px;
  padding:16px 17px;
  box-shadow:0 8px 22px rgba(64,31,52,.04);
}
.ub228-kpis span{
  display:block;
  color:#7A6973!important;
  font-size:11px!important;
  font-weight:800;
}
.ub228-kpis b{
  display:block;
  margin-top:5px;
  color:#4B1234!important;
  font-size:24px!important;
}
.ub228-kpis small{
  display:block;
  margin-top:3px;
  color:#8D7D86!important;
  font-size:10px!important;
}
.ub228-card{
  background:#fff;
  border:1px solid var(--v228-border);
  border-radius:18px;
  padding:18px;
  box-shadow:0 8px 24px rgba(64,31,52,.035);
}
.ub228-card-head{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:14px;
  margin-bottom:14px;
}
.ub228-card-head span{
  display:block;
  color:#9A8791!important;
  font-size:9px!important;
  font-weight:900;
  letter-spacing:.12em;
}
.ub228-card-head h2{
  margin:3px 0 0;
  color:#4B1234!important;
  font-size:17px!important;
}

/* Communication */
.ub228-comms-grid{
  display:grid;
  grid-template-columns:minmax(0,1.65fr) minmax(280px,.7fr);
  gap:14px;
  margin-bottom:14px;
}
.ub228-mini-seg{
  display:flex;
  gap:4px;
  padding:3px;
  background:#F4EFF2;
  border-radius:10px;
}
.ub228-mini-seg button{
  border:0;
  background:transparent;
  color:#6E5965;
  border-radius:7px;
  padding:6px 9px;
  font-weight:800;
}
.ub228-mini-seg button.active{
  background:#fff;
  color:#5A0B3B;
}
.ub228-week-row,
.ub228-month-grid{
  display:grid;
  grid-template-columns:repeat(7,1fr);
}
.ub228-week-row b{
  padding:6px 8px;
  text-align:center;
  color:#9A8791!important;
  font-size:9px!important;
}
.ub228-month-grid{
  border-left:1px solid #EEE7EB;
  border-top:1px solid #EEE7EB;
}
.ub228-month-grid>div{
  min-height:72px;
  border-right:1px solid #EEE7EB;
  border-bottom:1px solid #EEE7EB;
  padding:7px;
  background:#fff;
}
.ub228-month-grid>div.empty{background:#FBFAFB}
.ub228-month-grid strong{
  color:#4D3A45!important;
  font-size:10px!important;
}
.ub228-month-grid span{
  display:block;
  margin-top:5px;
  padding:4px 5px;
  border-radius:6px;
  font-size:8px!important;
  line-height:1.2;
}
.ub228-month-grid span.purple{background:#F4E7EF;color:#6A174B!important}
.ub228-month-grid span.orange{background:#FFF0E0;color:#A55300!important}
.ub228-month-grid span.green{background:#EAF7F2;color:#117456!important}
.ub228-ring-row{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:12px;
  margin:4px 0 18px;
}
.ub228-ring{
  aspect-ratio:1;
  max-width:130px;
  margin:auto;
  border-radius:50%;
  display:grid;
  place-items:center;
  align-content:center;
  background:conic-gradient(var(--v228-plum) calc(var(--p)*1%),#F0E9ED 0);
  position:relative;
}
.ub228-ring::after{
  content:"";
  position:absolute;
  inset:12px;
  background:#fff;
  border-radius:50%;
}
.ub228-ring b,.ub228-ring span{position:relative;z-index:1}
.ub228-ring b{font-size:21px!important;color:#4B1234!important}
.ub228-ring span{font-size:9px!important;color:#8A7983!important}
.ub228-segment-list>div,
.ub228-stat-pairs>div{
  display:flex;
  justify-content:space-between;
  gap:12px;
  padding:9px 0;
  border-top:1px solid #EFE9EC;
}
.ub228-segment-list span,.ub228-stat-pairs span{color:#75646E!important;font-size:10px!important}
.ub228-segment-list b,.ub228-stat-pairs b{color:#4B1234!important;font-size:11px!important}
.ub228-bottom-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:14px;
}
.ub228-schedule article,
.ub228-pub-list article{
  display:grid;
  grid-template-columns:auto auto minmax(0,1fr) auto;
  align-items:center;
  gap:10px;
  padding:10px 0;
  border-top:1px solid #EFE9EC;
}
.ub228-schedule article:first-child,
.ub228-pub-list article:first-child{border-top:0}
.ub228-schedule .date b{display:block;color:#4B1234!important;font-size:11px!important}
.ub228-schedule .date small{display:block;color:#9A8791!important;font-size:8px!important}
.ub228-schedule i{width:7px;height:30px;border-radius:10px;background:#7A1C57}
.ub228-schedule i.orange{background:#FF9B45}
.ub228-schedule i.green{background:#45A77A}
.ub228-schedule article>div:nth-child(3) b,
.ub228-pub-list article b{display:block;color:#4B1234!important;font-size:11px!important}
.ub228-schedule article>div:nth-child(3) small,
.ub228-pub-list article small{display:block;color:#8A7983!important;font-size:9px!important}
.ub228-schedule button{
  border:1px solid #E4D7DE;background:#fff;color:#5A0B3B;border-radius:8px;padding:6px 8px;font-weight:800
}
.ub228-pub-list article{grid-template-columns:minmax(0,1fr) auto auto}
.ub228-status{
  background:#EAF7F2!important;color:#147253!important;padding:5px 7px;border-radius:999px;font-size:8px!important;font-weight:900
}
.ub228-pub-list em{font-style:normal;color:#8A7983!important;font-size:8px!important}

/* Reports */
.ub228-filterbar{
  display:grid;
  grid-template-columns:repeat(4,minmax(160px,1fr));
  gap:10px;
  padding:12px;
  margin-bottom:14px;
  background:#fff;
  border:1px solid var(--v228-border);
  border-radius:14px;
}
.ub228-filterbar label{
  color:#83727C!important;
  font-size:9px!important;
  font-weight:800;
}
.ub228-filterbar select{
  width:100%;
  margin-top:5px;
  height:34px;
  border:1px solid #E5DCE1;
  border-radius:9px;
  background:#fff;
  color:#4A3943!important;
  padding:0 9px;
}
.ub228-report-grid{
  display:grid;
  grid-template-columns:1.25fr .75fr;
  gap:14px;
  margin-bottom:14px;
}
.ub228-report-grid .ub228-wide{grid-row:span 2}
.ub228-bars>div,
.ub228-dept-list>div{
  display:grid;
  grid-template-columns:minmax(120px,1.1fr) minmax(140px,2.4fr) 44px 92px;
  align-items:center;
  gap:10px;
  padding:9px 0;
}
.ub228-bars span,.ub228-dept-list span{color:#5C4A55!important;font-size:10px!important}
.ub228-bars b,.ub228-dept-list b{color:#4B1234!important;font-size:10px!important;text-align:right}
.ub228-bars small{color:#9A8791!important;font-size:8px!important;text-align:right}
.track{height:8px;background:#F0E9ED;border-radius:999px;overflow:hidden}
.track i{display:block;height:100%;background:linear-gradient(90deg,#6A174B,#B83C80);border-radius:999px}
.ub228-gender{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:10px;
}
.ub228-gender>div{
  padding:14px;
  background:#F8F5F7;
  border-radius:12px;
}
.ub228-gender strong{display:block;color:#4B1234!important;font-size:22px!important}
.ub228-gender span{color:#887680!important;font-size:9px!important}
.ub228-splitbar{height:10px;background:#F2D7E6;border-radius:999px;overflow:hidden;margin:12px 0}
.ub228-splitbar i{display:block;height:100%;background:#7A1C57}
.ub228-big-number{font-size:28px!important;font-weight:900;color:#4B1234!important}
.ub228-caption{display:block;color:#8A7983!important;font-size:9px!important;margin-bottom:14px}
.ub228-budget-legend>div{
  display:grid;
  grid-template-columns:auto 1fr auto;
  gap:8px;
  align-items:center;
  padding:7px 0;
}
.ub228-budget-legend i{width:9px;height:9px;border-radius:50%;background:#6B174C}
.ub228-budget-legend i.b{background:#C26B9C}
.ub228-budget-legend i.c{background:#F2BA85}
.ub228-budget-legend span{color:#75646E!important;font-size:9px!important}
.ub228-budget-legend b{color:#4B1234!important;font-size:10px!important}
.ub228-score b{font-size:38px!important;color:#4B1234!important}
.ub228-score span{font-size:14px!important;color:#9A8791!important}
.ub228-card>p{color:#7D6C76!important;font-size:10px!important}
.ub228-mini-metrics{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:8px;
  margin-top:14px;
}
.ub228-mini-metrics>div{background:#F8F5F7;border-radius:10px;padding:9px}
.ub228-mini-metrics span{display:block;color:#8A7983!important;font-size:8px!important}
.ub228-mini-metrics b{display:block;color:#4B1234!important;font-size:13px!important;margin-top:3px}
.ub228-dept-list>div{grid-template-columns:minmax(100px,1fr) minmax(120px,2fr) 40px}
.ub228-insights article{
  display:grid;
  grid-template-columns:30px minmax(0,1fr);
  gap:10px;
  align-items:start;
  padding:10px 0;
  border-top:1px solid #EFE9EC;
}
.ub228-insights article:first-of-type{border-top:0}
.ub228-insights i{
  display:grid;place-items:center;width:28px;height:28px;border-radius:9px;
  background:#F5E9F0;color:#6A174B;font-style:normal;font-weight:900
}
.ub228-insights b{display:block;color:#4B1234!important;font-size:10px!important}
.ub228-insights small{display:block;color:#82717B!important;font-size:9px!important;margin-top:2px}

@media(max-width:1180px){
  .ub228-kpis{grid-template-columns:repeat(2,1fr)}
  .ub228-comms-grid,.ub228-report-grid,.ub228-bottom-grid{grid-template-columns:1fr}
  .ub228-report-grid .ub228-wide{grid-row:auto}
}
@media(max-width:760px){
  .ub228-comms,.ub228-reports{padding:16px!important}
  .ub228-hero-row{display:block}
  .ub228-head-actions{justify-content:flex-start;margin-top:12px}
  .ub228-filterbar{grid-template-columns:1fr 1fr}
  .ub228-kpis{grid-template-columns:1fr 1fr}
}


/* ==========================================================
