.ub231-money-input{position:relative}
.ub231-money-input span{position:absolute;right:11px;bottom:11px;color:#8d7b85!important;font-size:10px!important}
.ub231-money-input input{padding-right:44px}
.ub231-source-row{margin-top:14px;padding-top:14px;border-top:1px solid #eee8eb}
.ub231-source-row>span{display:block;color:#6f5f68!important;font-size:10px!important;font-weight:800;margin-bottom:7px}
.ub231-source-row>div{display:flex;gap:6px;flex-wrap:wrap}
.ub231-source-row button{border:1px solid #e4d9df;background:#fff;color:#6b174e;border-radius:999px;padding:7px 10px;font-weight:800}
.ub231-source-row button.active{background:#f4e8ef;border-color:#cfa9be}
.ub231-calc-summary{background:linear-gradient(145deg,#641044,#3b0a2a)!important;color:#fff!important}
.ub231-result-hero span{display:block;color:#ffcc9a!important;font-size:9px!important;font-weight:900;letter-spacing:.12em}
.ub231-result-hero b{display:block;margin:10px 0 4px;color:#fff!important;font-size:34px!important}
.ub231-result-hero small{color:rgba(255,255,255,.78)!important}
.ub231-result-kpis{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:18px}
.ub231-result-kpis article{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.13);border-radius:11px;padding:11px}
.ub231-result-kpis span{display:block;color:rgba(255,255,255,.7)!important;font-size:9px!important}
.ub231-result-kpis b{display:block;margin-top:4px;color:#fff!important;font-size:15px!important}
.ub231-compare-card{margin-top:14px}
.ub231-cost-compare{margin-top:13px}
.ub231-cost-row{display:grid;grid-template-columns:160px 1fr 140px;align-items:center;gap:12px;margin:11px 0}
.ub231-cost-row span{color:#695964!important;font-size:10px!important}
.ub231-cost-row>div{height:12px;background:#f0e9ed;border-radius:999px;overflow:hidden}
.ub231-cost-row i{display:block;height:100%;background:#a36b8a;border-radius:999px}
.ub231-cost-row.is-up i{background:linear-gradient(90deg,#5a0b3b,#b33b7c)}
.ub231-cost-row b{text-align:right;color:#4b1234!important;font-size:11px!important}
.ub231-cost-delta{display:flex;justify-content:flex-end;align-items:center;gap:12px;padding-top:8px;border-top:1px solid #eee8eb}
.ub231-cost-delta span{color:#806e78!important;font-size:10px!important}
.ub231-cost-delta strong{color:#11825b!important;font-size:17px!important}
.ub231-calc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:14px}
.ub231-calc-grid article{background:#fff;border:1px solid #e7e0e4;border-radius:13px;padding:14px}
.ub231-calc-grid span{display:block;color:#806e78!important;font-size:9px!important;font-weight:800}
.ub231-calc-grid b{display:block;color:#4b1234!important;font-size:17px!important;margin-top:5px}
.ub231-calc-grid small{display:block;color:#9a8791!important;font-size:8px!important;margin-top:3px}
.ub231-calc-note{margin-top:14px;padding:14px 16px;border-radius:12px;background:#fff8ef;border:1px solid #f4d9b8}
.ub231-calc-note b{color:#6d3512!important}
.ub231-calc-note p{margin:4px 0 0;color:#795e4c!important;font-size:9px!important}

/* Reports — light Total Rewards layout inspired by modern HR analytics. */
.ub231-report-head{display:flex!important;justify-content:space-between;gap:20px}
.ub231-report-filters{
  display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:8px;
  padding:12px;margin:14px 0;background:#fff;border:1px solid #e7e0e4;border-radius:14px
}
.ub231-report-filters label{color:#85747e!important;font-size:8px!important;font-weight:800}
.ub231-report-filters select{
  width:100%;height:34px;margin-top:4px;border:1px solid #e0d8dd;border-radius:8px;background:#fff;color:#41323b!important;padding:0 8px
}
.ub231-report-tabs{display:flex;gap:4px;overflow:auto;margin-bottom:10px}
.ub231-report-tabs button{
  border:0;background:transparent;color:#786671;padding:9px 12px;border-radius:8px;font-weight:800;white-space:nowrap
}
.ub231-report-tabs button.active{background:#efe6eb;color:#5a0b3b}
.ub231-report-section{margin-bottom:10px}
.ub231-section-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:12px}
.ub231-section-head button{border:0;background:transparent;color:#5a0b3b;font-weight:800;cursor:pointer}
.ub231-pay-kpis,.ub231-total-grid{
  display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px
}
.ub231-pay-kpis{grid-template-columns:repeat(3,minmax(0,1fr))}
.ub231-pay-kpis article,.ub231-total-grid article{
  padding:13px;background:#faf9fa;border:1px solid #eee8eb;border-radius:11px
}
.ub231-pay-kpis span,.ub231-total-grid span{display:block;color:#7d6c76!important;font-size:9px!important}
.ub231-pay-kpis b,.ub231-total-grid b{display:block;color:#33252e!important;font-size:20px!important;margin-top:6px}
.ub231-pay-kpis small,.ub231-total-grid small{display:block;color:#988792!important;font-size:8px!important;margin-top:3px}
.ub231-pay-kpis small.warn,.ub231-variable-stats small.warn{color:#b96a20!important}
.ub231-pay-kpis small.ok{color:#147657!important}
.ub231-variable-grid{display:grid;grid-template-columns:.85fr 1.15fr;gap:12px}
.ub231-variable-stats{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.ub231-variable-stats article{padding:12px;border:1px solid #eee8eb;border-radius:10px;background:#fbfafb}
.ub231-variable-stats article:last-child{grid-column:1/-1}
.ub231-variable-stats span{display:block;color:#7d6c76!important;font-size:9px!important}
.ub231-variable-stats b{display:block;color:#33252e!important;font-size:17px!important;margin-top:5px}
.ub231-gender-stat{display:grid;grid-template-columns:auto 1fr auto 1fr;gap:5px;align-items:center;margin-top:7px}
.ub231-gender-stat b{font-size:14px!important}
.ub231-gender-stat span{font-size:8px!important}
.ub231-quartiles{padding:12px;border:1px solid #eee8eb;border-radius:10px;background:#fbfafb}
.ub231-mini-title{color:#5c4b55;font-size:9px;font-weight:900;margin-bottom:8px}
.ub231-qrow{display:grid;grid-template-columns:72px 1fr 70px;gap:8px;align-items:center;margin:8px 0}
.ub231-qrow>span{color:#6f5f68!important;font-size:8px!important}
.ub231-qrow>div{display:flex;height:12px;border-radius:999px;overflow:hidden;background:#efe8ec}
.ub231-qrow i,.ub231-qrow em{display:block;height:100%}
.ub231-qrow i{background:#335fa9}.ub231-qrow em{background:#c92275}
.ub231-qrow small{color:#8f7e88!important;font-size:8px!important;text-align:right}
.ub231-total-grid.compact article b{font-size:18px!important}
.ub231-report-two{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.ub231-benefit-bars>div,.ub231-dept-bars>div{
  display:grid;grid-template-columns:140px 1fr 50px 110px;gap:9px;align-items:center;margin:10px 0
}
.ub231-dept-bars>div{grid-template-columns:130px 1fr 45px}
.ub231-benefit-bars span,.ub231-dept-bars span{color:#6f5f68!important;font-size:9px!important}
.ub231-benefit-bars>div>div,.ub231-dept-bars>div>div{height:8px;background:#f0e9ed;border-radius:999px;overflow:hidden}
.ub231-benefit-bars i,.ub231-dept-bars i{display:block;height:100%;background:linear-gradient(90deg,#5a0b3b,#b63d7f);border-radius:999px}
.ub231-benefit-bars b,.ub231-dept-bars b{color:#4b1234!important;font-size:9px!important;text-align:right}
.ub231-benefit-bars small{color:#95838e!important;font-size:8px!important;text-align:right}
.ub231-donut-row{display:grid;grid-template-columns:130px 1fr;gap:15px;align-items:center}
.ub231-donut{
  width:120px;height:120px;border-radius:50%;display:grid;place-items:center;align-content:center;
  background:conic-gradient(#6a174b calc(var(--used)*1%),#eee7eb 0);position:relative
}
.ub231-donut:after{content:"";position:absolute;inset:14px;background:#fff;border-radius:50%}
.ub231-donut b,.ub231-donut span{position:relative;z-index:1}
.ub231-donut b{color:#4b1234!important;font-size:19px!important}
.ub231-donut span{color:#8f7e88!important;font-size:8px!important}
.ub231-budget-list>div{display:flex;justify-content:space-between;gap:8px;padding:7px 0;border-top:1px solid #eee8eb}
.ub231-budget-list span{color:#75646e!important;font-size:9px!important}
.ub231-budget-list b{color:#4b1234!important;font-size:9px!important}
.ub231-ranking>div{display:grid;grid-template-columns:24px 1fr auto;gap:7px;align-items:center;padding:8px 0;border-top:1px solid #eee8eb}
.ub231-ranking>div:first-child{border-top:0}
.ub231-ranking b{display:grid;place-items:center;width:21px;height:21px;border-radius:7px;background:#f3e8ee;color:#6a174b!important;font-size:9px!important}
.ub231-ranking span{color:#594751!important;font-size:9px!important}
.ub231-ranking em{font-style:normal;color:#8b7983!important;font-size:8px!important}
.ub231-export-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}
.ub231-export-grid button{display:flex;align-items:center;gap:8px;padding:12px;border:1px solid #e6dde2;border-radius:10px;background:#fff;text-align:left;cursor:pointer}
.ub231-export-grid button>span{font-size:18px;color:#6a174b!important}
.ub231-export-grid b{display:block;color:#4b1234!important;font-size:9px!important}
.ub231-export-grid small{display:block;color:#8f7e88!important;font-size:8px!important}

/* HR Codes — exactly the same card family/data as employee. */
.ub231-code-summary{
  display:flex;align-items:center;gap:10px;margin:12px 0;padding:11px 13px;border:1px solid #e5dce1;border-radius:11px;background:#fff
}
.ub231-code-summary b{color:#4b1234!important}.ub231-code-summary span{color:#7e6d77!important;font-size:9px!important}
.ub231-client-code-grid article{position:relative}
.ub231-client-code-grid article.is-hidden{opacity:.58}
.ub231-client-code{
  display:grid;grid-template-columns:auto 1fr auto;gap:8px;align-items:center;padding:9px;margin-top:10px;background:#f8f2f5;border-radius:9px
}
.ub231-client-code span{color:#8b7983!important;font-size:8px!important;font-weight:900}
.ub231-client-code b{color:#4b1234!important;font-size:12px!important;letter-spacing:.04em}
.ub231-client-code button{border:0;background:#fff;color:#5a0b3b;border-radius:7px;padding:6px 8px;font-weight:800}
.ub231-client-code-grid footer{display:flex;justify-content:space-between;align-items:center;margin-top:10px;padding-top:9px;border-top:1px solid #eee7eb}
.ub231-client-code-grid footer>button{border:1px solid #dfd4da;background:#fff;color:#5a0b3b;border-radius:7px;padding:6px 8px;font-weight:800}

@media(max-width:1180px){
  .ub231-report-filters{grid-template-columns:repeat(3,1fr)}
  .ub231-calc-layout,.ub231-variable-grid,.ub231-report-two{grid-template-columns:1fr}
  .ub231-calc-grid{grid-template-columns:1fr 1fr}
}
@media(max-width:760px){
  .ub231-calc-page,.ub231-reports,.ub231-client-codes{padding:16px!important}
  .ub231-calc-head,.ub231-report-head{display:block!important}
  .ub231-calc-presets{margin-top:10px}
  .ub231-calc-form,.ub231-pay-kpis,.ub231-total-grid{grid-template-columns:1fr 1fr}
  .ub231-report-filters{grid-template-columns:1fr 1fr}
  .ub231-cost-row{grid-template-columns:110px 1fr}
  .ub231-cost-row b{grid-column:2}
  .ub231-benefit-bars>div{grid-template-columns:100px 1fr 42px}
  .ub231-benefit-bars small{display:none}
  .ub231-export-grid{grid-template-columns:1fr 1fr}
}


/* ===== SOURCE: upbonus-v229-footer-and-contrast.css ===== */
/* ==========================================================
   UP BONUS V229 — FOOTER EVERYWHERE + DARK SURFACE CONTRAST
   No layout redesign outside footer containment/contrast.
========================================================== */

/* Role main and account chooser become column shells so the footer sits
   at the bottom on short screens and after content on long screens. */
.role-app .main-content,
.v34-account-page,
.account-page{
  display:flex!important;
  flex-direction:column!important;
  min-height:100%!important;
  padding-bottom:0!important;
}

.role-app .main-content>.view-container,
.v34-account-page>.container,
.account-page>.container{
  flex:1 0 auto!important;
}

/* ZERO white stripe between content and footer. */
.v45-footer.ub229-footer{
  flex:0 0 auto!important;
  width:100%!important;
  max-width:none!important;
  margin:0!important;
  margin-top:auto!important;
  padding:32px clamp(24px,5vw,72px) 22px!important;
  box-sizing:border-box!important;
  background:#2F0B22!important;
  border-top:4px solid #FF8500!important;
  border-radius:0!important;
  color:#fff!important;
  -webkit-text-fill-color:currentColor!important;
  box-shadow:none!important;
}

/* V230: translated/replaced text nodes must never inherit dark text. */
.v45-footer.ub229-footer,
.v45-footer.ub229-footer :is(h1,h2,h3,h4,h5,h6,p,a,span,small,b,strong,li,em){
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
  opacity:1!important;
}

/* No white rectangle in logo/columns. */
.v45-footer.ub229-footer .v45-footer-grid,
.v45-footer.ub229-footer .v45-footer-grid>div,
.v45-footer.ub229-footer .v45-footer-links,
.v45-footer.ub229-footer .v45-footer-legal,
.v45-footer.ub229-footer .v45-footer-logo{
  background:transparent!important;
  border:0!important;
  box-shadow:none!important;
}

.v45-footer.ub229-footer .v45-footer-logo{
  display:block!important;
  width:auto!important;
  min-width:0!important;
  height:auto!important;
  min-height:0!important;
  padding:0!important;
  margin:0 0 10px!important;
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
  font-size:24px!important;
  font-weight:900!important;
  line-height:1.1!important;
}

.v45-footer.ub229-footer .v45-footer-grid{
  display:grid!important;
  grid-template-columns:1.05fr .9fr 1fr!important;
  gap:42px!important;
}

.v45-footer.ub229-footer h3{
  margin:0 0 12px!important;
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
  font-size:13px!important;
  text-transform:uppercase;
  letter-spacing:.04em;
}

.v45-footer.ub229-footer p,
.v45-footer.ub229-footer a,
.v45-footer.ub229-footer span,
.v45-footer.ub229-footer small{
  color:rgba(255,255,255,.9)!important;
  -webkit-text-fill-color:currentColor!important;
}

.v45-footer.ub229-footer p{
  margin:4px 0!important;
  line-height:1.45!important;
}

.v45-footer.ub229-footer .v45-footer-links{
  display:grid!important;
  gap:8px!important;
}

.v45-footer.ub229-footer .v45-footer-legal{
  margin-top:28px!important;
  padding-top:18px!important;
  border-top:1px solid rgba(255,255,255,.16)!important;
  text-align:center!important;
  color:rgba(255,255,255,.78)!important;
  -webkit-text-fill-color:currentColor!important;
}

/* Absolutely remove old decorative/footer pseudo blocks. */
.v45-footer.ub229-footer::before,
.v45-footer.ub229-footer::after{
  content:none!important;
  display:none!important;
}

/* Account chooser: no pale/white footer mode. */
.v34-account-page>.v45-footer.ub229-footer,
.account-page>.v45-footer.ub229-footer{
  margin-top:0!important;
}

/* ---------- Burgundy/dark surfaces: never black text ---------- */
.v33-gift-spotlight{
  color:#fff!important;
  -webkit-text-fill-color:currentColor!important;
}
.v33-gift-spotlight .v33-gift-copy h2{
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
}
.v33-gift-spotlight .v33-gift-copy>p{
  color:rgba(255,255,255,.86)!important;
  -webkit-text-fill-color:currentColor!important;
}
.v33-gift-spotlight .v33-gift-kicker{
  color:#FFE2F2!important;
  -webkit-text-fill-color:currentColor!important;
}
.v33-gift-spotlight .v33-gift-points span{
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
}
.v33-gift-spotlight .v33-secondary{
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
}
.v33-gift-spotlight .v33-primary{
  background:#fff!important;
  color:#6B174E!important;
  -webkit-text-fill-color:#6B174E!important;
}
.v33-gift-spotlight .v33-card-content,
.v33-gift-spotlight .v33-card-message,
.v33-gift-spotlight .v33-card-foot,
.v33-gift-spotlight .v33-card-logo{
  color:#fff!important;
  -webkit-text-fill-color:currentColor!important;
}

/* Other known branded dark blocks stay readable. */
:is(
  .hero-main,
  .ub119-funds,
  .ub122-premium-services,
  .employee-hero,
  .employee-banner
) :is(h1,h2,h3,h4,p,span,small,b,strong,label){
  -webkit-text-fill-color:currentColor!important;
}

/* Footer must remain responsive. */

/* V230: every authored burgundy hero uses light typography. */
.v33-gift-spotlight :is(h1,h2,h3,h4,p,span,small,b,strong,label,em),
.ub122-premium-services .ub122-premium-head :is(h1,h2,h3,h4,p,span,small,b,strong,label,em){
  color:#fff!important;
  -webkit-text-fill-color:#fff!important;
  opacity:1!important;
}
.v33-gift-spotlight .v33-primary,
.ub122-premium-services .ub122-premium-grid>button,
.ub122-premium-services .ub122-premium-grid>button :is(b,strong,small,span,em){
  color:#5A0B3B!important;
  -webkit-text-fill-color:#5A0B3B!important;
}

@media(max-width:850px){
  .v45-footer.ub229-footer .v45-footer-grid{
    grid-template-columns:1fr!important;
    gap:22px!important;
  }
}


/* 060 — employee home visual benchmark refresh */
.v60-home{max-width:1240px;margin:0 auto;padding-bottom:28px}
.v60-home-top{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(330px,.7fr);gap:16px;margin-bottom:16px}
.v60-intro{min-height:270px;border-radius:24px;padding:34px 36px;background:linear-gradient(135deg,var(--brand-primary),#3a1530);color:#fff;display:flex;flex-direction:column;justify-content:center;box-shadow:0 14px 34px rgba(84,25,65,.14)}
.v60-intro .eyebrow{color:rgba(255,255,255,.68);font-size:10px;letter-spacing:.13em;font-weight:900}
.v60-intro h1{font-size:clamp(34px,4vw,50px);margin:9px 0 10px;letter-spacing:-.04em}
.v60-intro p{max-width:650px;margin:0;color:rgba(255,255,255,.78);font-size:13px;line-height:1.65}
.v60-home-actions{display:flex;gap:9px;margin-top:22px;flex-wrap:wrap}
.v60-home-actions .primary-btn{background:#fff;color:var(--brand-primary);border-color:#fff}
.v60-home-actions .secondary-btn{background:rgba(255,255,255,.08);color:#fff;border-color:rgba(255,255,255,.25)}
.v60-wallet{background:#fff;border:1px solid var(--brand-border);border-radius:24px;padding:22px;box-shadow:0 10px 30px rgba(42,20,38,.06)}
.v60-wallet-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding-bottom:13px;border-bottom:1px solid var(--brand-border)}
