/* ============================================================
   V218 — Clients registry: premium spreadsheet + viewport fit
   No horizontal slider. Low-priority columns collapse by width.
   ============================================================ */
.page-content.ub217-page{
  width:100%!important;
  max-width:none!important;
  min-width:0!important;
  box-sizing:border-box!important;
  overflow-x:clip!important;
  padding-left:clamp(18px,2.2vw,34px)!important;
  padding-right:clamp(18px,2.2vw,34px)!important;
}
.ub217-page *{box-sizing:border-box}
.ub217-page .ub217-head{margin-bottom:12px}
.ub217-page .ub217-head h1{font-size:clamp(26px,2vw,34px);letter-spacing:-.035em;margin:3px 0 4px}
.ub217-page .ub217-head p{max-width:760px}
.ub217-register{min-width:0;background:#fff;border:1px solid #e9e2e7;border-radius:14px;box-shadow:0 8px 26px rgba(49,29,44,.035);overflow:hidden}
