.ub217-register .ub217-toolbar label{min-width:160px!important;flex:1 1 360px!important;height:36px!important}
.ub217-register .ub217-toolbar input,.ub217-register .ub217-toolbar select{height:34px!important;font-size:11px!important}
.ub217-register .ub217-toolbar select{flex:0 1 160px;min-width:118px;max-width:180px}
.ub217-export{height:34px;border:1px solid #d9cbd4;background:#fff;color:#6d164f;border-radius:9px;padding:0 11px;font-size:11px;font-weight:800;cursor:pointer;white-space:nowrap}
