.ub217-register .ub217-sheet th:nth-child(2){width:16%!important}
.ub217-register .ub217-sheet th:nth-child(3){width:10%!important}
.ub217-register .ub217-sheet th:nth-child(4){width:7%!important}
.ub217-register .ub217-sheet th:nth-child(5){width:11%!important}
.ub217-register .ub217-sheet th:nth-child(6){width:16%!important}
.ub217-register .ub217-sheet th:nth-child(7){width:7%!important}
.ub217-register .ub217-sheet th:nth-child(8){width:9%!important}
