/* editor */
body.ub217-modal-open{overflow:hidden!important}
.ub217-edit-backdrop{position:fixed;inset:0;z-index:10050;background:rgba(39,23,34,.28);backdrop-filter:blur(3px);display:flex;align-items:center;justify-content:center;padding:24px}
.ub217-edit-modal{width:min(760px,calc(100vw - 40px));max-height:min(760px,calc(100vh - 40px));overflow:auto;background:#fff;border:1px solid #e8dfe5;border-radius:18px;box-shadow:0 28px 80px rgba(49,29,44,.2)}
