.ub217-edit-modal>header>button{width:34px;height:34px;border:1px solid #e7dfe4;border-radius:10px;background:#fff;color:#6d164f;font-size:21px;line-height:1;cursor:pointer}
.ub217-edit-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px;padding:18px 22px}.ub217-edit-grid label{display:flex;flex-direction:column;gap:5px}.ub217-edit-grid label.wide{grid-column:1/-1}.ub217-edit-grid span{font-size:10px;font-weight:800;color:#70636c}.ub217-edit-grid input,.ub217-edit-grid select,.ub217-edit-grid textarea{width:100%;border:1px solid #e7dfe4;border-radius:9px;background:#fff;color:#3e333b;font:inherit;font-size:12px;padding:9px 10px;outline:none}.ub217-edit-grid input:focus,.ub217-edit-grid select:focus,.ub217-edit-grid textarea:focus{border-color:#a47592;box-shadow:0 0 0 3px rgba(109,22,79,.06)}.ub217-edit-grid input[type=color]{height:39px;padding:4px}.ub217-edit-modal>footer{display:flex;justify-content:flex-end;gap:8px;padding:14px 22px 20px;border-top:1px solid #f0ebee}

/* Scaling: never create horizontal scrollbar for client registry. */
@media(max-width:1380px){
  .ub217-register .ub217-sheet th:nth-child(1){width:31%!important}
  .ub217-register .ub217-sheet th:nth-child(2){width:17%!important}
  .ub217-register .ub217-sheet th:nth-child(3){width:11%!important}
  .ub217-register .ub217-sheet th:nth-child(4){width:7%!important}
  .ub217-register .ub217-sheet th:nth-child(5){width:12%!important}
